// .orchestrator/types.ts
// Le plan est une STRUCTURE DE DONNÉES, pas une liste de souhaits en prose.
// Ce qui est typé peut être vérifié par un script ; ce qui est en prose ne peut
// être vérifié que par quelqu'un qui relit tout.

export interface Task {
  id: string;                         // "T-001", stable, jamais réutilisé
  title: string;
  epic: string;
  /** Borne haute. Au-delà, la fiabilité de l'agent se dégrade : on redécoupe. */
  estimatedMinutes: number;
  /** Périmètre modifiable. Une tâche qui touche tout n'est pas atomique. */
  scope: { allowedPaths: string[]; forbiddenPaths: string[] };
  /** Vérifiables sans comprendre l'implémentation : c'est le critère. */
  acceptance: AcceptanceCriterion[];
  dependsOn: string[];
  assignedSkill: SkillName;
  status: "todo" | "in_progress" | "blocked" | "done";
}

export interface AcceptanceCriterion {
  /** Une COMMANDE, pas une intention. "Le code est propre" n'est pas vérifiable. */
  check: string;                      // "npx vitest run src/auth"
  expect: "exit_zero" | "output_contains";
  value?: string;
}

// ---------------------------------------------------------------------------
// .orchestrator/validate-plan.ts
// Le plan est validé AVANT la première exécution. Un plan défaillant produit
// des heures de travail à refaire, et le défaut est toujours visible en amont.

const MAX_TASK_MINUTES = 120;

export function validatePlan(tasks: Task[]): string[] {
  const errors: string[] = [];
  const byId = new Map(tasks.map((t) => [t.id, t]));

  for (const t of tasks) {
    // 1. Granularité. La règle la plus simple et la plus souvent violée.
    if (t.estimatedMinutes > MAX_TASK_MINUTES) {
      errors.push(`${t.id} : ${t.estimatedMinutes} min > ${MAX_TASK_MINUTES}. Redécouper.`);
    }

    // 2. Vérifiabilité. Un critère non exécutable n'est pas un critère.
    if (t.acceptance.length < 2) {
      errors.push(`${t.id} : moins de 2 critères d'acceptation.`);
    }
    for (const a of t.acceptance) {
      if (!/^(npm|npx|node|bash|curl|git)\s/.test(a.check)) {
        errors.push(`${t.id} : critère non exécutable « ${a.check} ».`);
      }
    }

    // 3. Atomicité du périmètre. Sans borne, un échec contamine tout le dépôt.
    if (t.scope.allowedPaths.length === 0 || t.scope.allowedPaths.includes("**")) {
      errors.push(`${t.id} : périmètre non borné.`);
    }

    // 4. Dépendances résolvables et acycliques.
    for (const d of t.dependsOn) {
      if (!byId.has(d)) errors.push(`${t.id} : dépendance inconnue ${d}.`);
    }
  }

  const cycle = findCycle(tasks);
  if (cycle) errors.push(`Cycle de dépendances : ${cycle.join(" → ")}.`);

  return errors;
}

// ---------------------------------------------------------------------------
// .orchestrator/gate.ts
// La validation exécute les critères. Elle ne lit pas le rapport de l'agent :
// un agent qui déclare « tests passés » déclare, il ne prouve pas.

export async function runGate(task: Task): Promise<GateResult> {
  const results: CheckResult[] = [];

  for (const criterion of task.acceptance) {
    const { code, stdout } = await exec(criterion.check, { timeout: 300_000 });
    const passed =
      criterion.expect === "exit_zero" ? code === 0 : stdout.includes(criterion.value!);
    results.push({ check: criterion.check, passed, output: stdout.slice(-2_000) });
  }

  // Hors périmètre : une tâche qui modifie des fichiers non autorisés échoue,
  // même si tous ses tests passent. C'est la garantie d'atomicité.
  const touched = await exec("git diff --name-only HEAD");
  const outOfScope = touched.stdout
    .split("\n")
    .filter((f) => f && !task.scope.allowedPaths.some((p) => minimatch(f, p)));

  if (outOfScope.length > 0) {
    results.push({ check: "périmètre", passed: false, output: outOfScope.join("\n") });
  }

  return { taskId: task.id, passed: results.every((r) => r.passed), results };
}

// ---------------------------------------------------------------------------
// Reprise : la propriété qu'on néglige et qui distingue un pipeline d'une conversation.

export function nextTask(tasks: Task[]): Task | null {
  return (
    tasks.find(
      (t) =>
        t.status === "todo" &&
        t.dependsOn.every((d) => tasks.find((x) => x.id === d)?.status === "done"),
    ) ?? null
  );
}
// L'état vit dans les fichiers, pas dans la session. Une interruption ne coûte
// que la tâche en cours, jamais les précédentes.

// .orchestrator/skills.ts
// Un skill n'est pas un autre modèle : c'est un CADRAGE nommé.
// Consignes, outils, contexte et format de sortie — les quatre varient ensemble.

export interface Skill {
  name: SkillName;
  systemPrompt: string;
  /** Restriction d'outils : fiabilité ET sûreté. Un rédacteur n'exécute rien. */
  allowedTools: ToolName[];
  /** Ce que l'agent reçoit. Gouverné par SOUSTRACTION. */
  contextSelectors: string[];
  /** Analysable par script : c'est ce qui rend la validation automatisable. */
  outputSchema: z.ZodTypeAny;
}

const ReportSchema = z.object({
  filesChanged: z.array(z.string()),
  commandsRun: z.array(z.object({ cmd: z.string(), exitCode: z.number() })),
  assumptions: z.array(z.string()),
  // Déclaratif : il sera CONFRONTÉ à l'exécution réelle, jamais cru sur parole.
  selfAssessment: z.enum(["complete", "partial", "blocked"]),
});

export const SKILLS: Record<SkillName, Skill> = {
  "db-migration": {
    name: "db-migration",
    systemPrompt: [
      "Tu réalises des migrations de schéma. Règles non négociables :",
      "- toute migration est additive ; une suppression se fait en deux déploiements",
      "- aucune migration ne verrouille une table plus de 2 secondes",
      "- toute migration est accompagnée de son chemin de retour arrière",
      "Tu ne touches ni à l'interface, ni aux styles, ni à la documentation.",
    ].join("\n"),
    // Pas d'accès réseau : une migration n'appelle pas de service externe.
    allowedTools: ["file_read", "file_write", "run_sql", "run_tests"],
    // Les conventions d'interface n'apportent RIEN ici : elles diluent.
    contextSelectors: ["prisma/schema.prisma", "prisma/migrations/**", "docs/db-conventions.md"],
    outputSchema: ReportSchema,
  },

  "docs-writer": {
    name: "docs-writer",
    systemPrompt: "Tu rédiges de la documentation technique en français. Tu ne modifies aucun code.",
    // Aucune exécution. Le lui interdire coûte une ligne ; lui faire confiance, un incident.
    allowedTools: ["file_read", "file_write"],
    contextSelectors: ["docs/**", "README.md", "src/**/*.d.ts"],
    outputSchema: ReportSchema,
  },
};

// ---------------------------------------------------------------------------
// .orchestrator/context.ts — le contexte se gouverne par SOUSTRACTION.

export async function buildContext(skill: Skill, task: Task) {
  const files = await resolveSelectors(skill.contextSelectors);

  // Borne dure. Au-delà, on ne fournit pas « plus d'information » :
  // on dilue celle qui compte. Mieux vaut un contexte réduit et pertinent.
  const budget = 30_000;
  let used = 0;
  const kept: string[] = [];

  // Les fichiers du périmètre de la tâche passent en premier : ce sont les seuls
  // dont l'agent a besoin intégralement.
  const ordered = [...files].sort(
    (a, b) => scoreRelevance(b, task) - scoreRelevance(a, task),
  );

  for (const f of ordered) {
    const content = await read(f);
    if (used + content.length > budget) continue;
    kept.push(`--- ${f} ---\n${content}`);
    used += content.length;
  }
  return kept.join("\n\n");
}

// ---------------------------------------------------------------------------
// .orchestrator/dispatch.ts — composition déterministe du prompt.

export async function dispatch(task: Task) {
  const skill = SKILLS[task.assignedSkill];

  const prompt = [
    skill.systemPrompt,
    `\n## Contexte projet\n${await buildContext(skill, task)}`,
    `\n## Tâche ${task.id} — ${task.title}\n${task.description}`,
    `\n## Périmètre autorisé\n${task.scope.allowedPaths.join("\n")}`,
    `\n## Critères d'acceptation (ils seront EXÉCUTÉS)\n` +
      task.acceptance.map((a) => `- ${a.check}`).join("\n"),
    `\n## Format de sortie\n${describeSchema(skill.outputSchema)}`,
  ].join("\n");

  const raw = await agent.run({ prompt, tools: skill.allowedTools });

  // Format non respecté = tâche rejetée. Sans cette rigueur, la validation
  // redevient manuelle et le dispositif est abandonné en quelques jours.
  const parsed = skill.outputSchema.safeParse(raw);
  if (!parsed.success) {
    return { status: "rejected", reason: "format de sortie invalide", issues: parsed.error.issues };
  }

  // L'affirmation de l'agent est CONFRONTÉE à l'exécution réelle.
  const gate = await runGate(task);
  if (parsed.data.selfAssessment === "complete" && !gate.passed) {
    logger.warn({ task: task.id }, "L'agent se déclare complet alors que la validation échoue.");
  }
  return { status: gate.passed ? "done" : "failed", report: parsed.data, gate };
}

# PROGRESS.md — contrat de suivi lisible par l'humain et par l'agent
