// scripts/drift-check.ts — détection mécanique de la dérive
// Exécuté après chaque itération : coupe la boucle avant qu'elle ne s'emballe.
import { readFileSync } from "node:fs";

type Snapshot = {
  iteration: number;
  doneCount: number;
  reopenedCount: number;
  decisionCount: number;
};

export type DriftVerdict =
  | { ok: true }
  | { ok: false; reason: string; action: "stop" | "escalate" };

const MAX_STALLED_ITERATIONS = 2;  // itérations consécutives sans progrès
const MAX_REOPENED = 3;            // une tâche refaite en boucle = spec floue

export function detectDrift(history: Snapshot[]): DriftVerdict {
  if (history.length < 2) return { ok: true };

  const current = history[history.length - 1]!;

  // 1. Progrès réel : le nombre de tâches terminées doit augmenter.
  const stalled = history
    .slice(-(MAX_STALLED_ITERATIONS + 1))
    .every((s, i, arr) => i === 0 || s.doneCount === arr[i - 1]!.doneCount);

  if (stalled && history.length > MAX_STALLED_ITERATIONS) {
    return {
      ok: false,
      reason: `Aucune tâche terminée depuis ${MAX_STALLED_ITERATIONS} itérations.`,
      action: "stop",
    };
  }

  // 2. Réouvertures : l'agent défait ce qu'il a fait = objectif mal défini.
  if (current.reopenedCount >= MAX_REOPENED) {
    return {
      ok: false,
      reason: `${current.reopenedCount} tâches rouvertes : la spécification est ambiguë.`,
      action: "escalate",
    };
  }

  // 3. Décisions figées : si elles diminuent, l'agent a réécrit l'historique.
  const previous = history[history.length - 2]!;
  if (current.decisionCount < previous.decisionCount) {
    return {
      ok: false,
      reason: "Des décisions figées ont disparu de PROGRESS.md.",
      action: "stop",
    };
  }

  return { ok: true };
}

// Boucle d'orchestration : la vérification est un passage obligé, pas une option.
export async function runIteration(history: Snapshot[]) {
  const verdict = detectDrift(history);
  if (!verdict.ok) {
    console.error(`[DRIFT] ${verdict.reason}`);
    if (verdict.action === "stop") process.exit(1);
    await notifyHuman(verdict.reason);
    return;
  }
  await delegateNextTask(readFileSync("PROGRESS.md", "utf8"));
}

// orchestration/task-contract.ts
// Le contrat de tâche est une donnée, pas une phrase dans un prompt.
// Il est validé avant délégation : une tâche invalide n'atteint jamais l'agent.

import { z } from "zod";

export const TaskContract = z.object({
  id: z.string().regex(/^T\d+$/, "Identifiant attendu : T1, T2, …"),
  intent: z.string().min(20, "Décris l'intention, pas le geste technique."),

  // Entrées : ce que l'agent a le droit de lire. Tout le reste est hors champ.
  inputs: z.object({
    readableFiles: z.array(z.string()).min(1),
    frozenDecisions: z.array(z.string()).default([]),
  }),

  // Sortie : un artefact nommé, vérifiable par une commande.
  output: z.object({
    artifact: z.string().min(1),
    verifyCommand: z.string().min(1),
  }),

  // Périmètre d'écriture : liste blanche explicite.
  writableFiles: z.array(z.string()).min(1),

  dependsOn: z.array(z.string()).default([]),
  rollback: z.string().min(1),
});

export type TaskContract = z.infer<typeof TaskContract>;

/** Refuse une tâche non déléguable avant de dépenser le moindre jeton. */
export function assertDeleguable(raw: unknown): TaskContract {
  const task = TaskContract.parse(raw);

  // Close : le critère doit être exécutable, pas déclaratif.
  if (/^(vérifier|s'assurer|valider) que/i.test(task.output.verifyCommand)) {
    throw new Error(
      `${task.id} : le critère est une phrase, pas une commande. ` +
        `Attendu : « npm test -- billing » ou « tsc --noEmit ».`,
    );
  }

  // Isolée : on ne peut pas écrire dans un fichier qu'on n'a pas le droit de lire.
  const unreadable = task.writableFiles.filter(
    (f) => !task.inputs.readableFiles.some((r) => f.startsWith(r.replace(/\*+$/, ""))),
  );
  if (unreadable.length) {
    throw new Error(`${task.id} : écriture hors périmètre de lecture → ${unreadable.join(", ")}`);
  }

  return task;
}

// ---------------------------------------------------------------------------
// orchestration/delegate.ts — délégation derrière contrat

export async function delegate(task: TaskContract, agent: Agent) {
  const prompt = [
    `Tâche ${task.id} — ${task.intent}`,
    ``,
    `Fichiers lisibles : ${task.inputs.readableFiles.join(", ")}`,
    `Fichiers modifiables : ${task.writableFiles.join(", ")}`,
    task.inputs.frozenDecisions.length
      ? `Décisions figées (ne pas rouvrir) :\n- ${task.inputs.frozenDecisions.join("\n- ")}`
      : ``,
    ``,
    `Livrable attendu : ${task.output.artifact}`,
    `Ton travail est terminé quand « ${task.output.verifyCommand} » réussit.`,
    `N'écris dans aucun autre fichier. Si c'est nécessaire, arrête-toi et explique pourquoi.`,
  ]
    .filter(Boolean)
    .join("\n");

  const result = await agent.run(prompt);

  // La vérification est exécutée par l'orchestrateur, jamais rapportée par l'agent.
  const { exitCode, stdout } = await sh(task.output.verifyCommand);
  if (exitCode !== 0) {
    await sh(task.rollback);
    return { id: task.id, status: "failed" as const, log: stdout };
  }

  // Contrôle du périmètre : un agent qui déborde invalide le lot entier.
  const touched = await sh("git diff --name-only");
  const outOfScope = touched.stdout
    .split("\n")
    .filter(Boolean)
    .filter((f) => !task.writableFiles.includes(f));

  if (outOfScope.length) {
    await sh(task.rollback);
    return { id: task.id, status: "out_of_scope" as const, log: outOfScope.join(", ") };
  }

  return { id: task.id, status: "done" as const, log: result.summary };
}

// orchestration/scheduler.ts
// Ordonnancement par vagues : on ne parallélise que ce que le graphe autorise.

import type { TaskContract } from "./task-contract";

/** Découpe le graphe en vagues exécutables en parallèle. Détecte les cycles. */
export function planWaves(tasks: TaskContract[]): TaskContract[][] {
  const byId = new Map(tasks.map((t) => [t.id, t]));
  const done = new Set<string>();
  const waves: TaskContract[][] = [];

  let remaining = [...tasks];
  while (remaining.length) {
    const ready = remaining.filter((t) => t.dependsOn.every((d) => done.has(d)));

    if (!ready.length) {
      throw new Error(
        `Cycle de dépendances détecté entre : ${remaining.map((t) => t.id).join(", ")}`,
      );
    }

    // Garde-fou : deux tâches d'une même vague ne peuvent pas écrire au même endroit.
    assertDisjointScopes(ready);

    waves.push(ready);
    ready.forEach((t) => done.add(t.id));
    remaining = remaining.filter((t) => !done.has(t.id));
  }

  // Dépendance vers une tâche inexistante : erreur de découpage, pas d'exécution.
  for (const t of tasks) {
    for (const d of t.dependsOn) {
      if (!byId.has(d)) throw new Error(`${t.id} dépend de ${d}, qui n'existe pas.`);
    }
  }

  return waves;
}

function assertDisjointScopes(wave: TaskContract[]) {
  const seen = new Map<string, string>();
  for (const task of wave) {
    for (const file of task.writableFiles) {
      const owner = seen.get(file);
      if (owner) {
        throw new Error(
          `${task.id} et ${owner} écrivent tous deux dans ${file}. ` +
            `Extrayez ce fichier dans une tâche de contrat préalable.`,
        );
      }
      seen.set(file, task.id);
    }
  }
}

// ---------------------------------------------------------------------------
// orchestration/run-wave.ts — exécution isolée par branche

export async function runWave(wave: TaskContract[], maxParallel: number) {
  const results: WaveResult[] = [];

  // Le parallélisme est borné par la capacité de relecture, pas par la machine.
  for (const chunk of chunkBy(wave, maxParallel)) {
    const settled = await Promise.allSettled(
      chunk.map(async (task) => {
        const branch = `wip/${task.id}`;
        await sh(`git switch -c ${branch} main`);
        try {
          const r = await delegate(task, pickAgent(task));
          if (r.status !== "done") {
            await sh(`git switch main && git branch -D ${branch}`);
            return { task, status: r.status, branch: null };
          }
          return { task, status: "done" as const, branch };
        } finally {
          await sh("git switch main");
        }
      }),
    );

    for (const s of settled) {
      results.push(s.status === "fulfilled" ? s.value : { task: null, status: "crashed" });
    }

    // Intégration incrémentale : on fusionne dès que possible, pas à la fin.
    for (const r of results.filter((r) => r.branch)) {
      const merge = await sh(`git merge --no-ff ${r.branch}`);
      if (merge.exitCode !== 0) {
        await sh("git merge --abort");
        r.status = "conflict";
        continue;
      }
      const integration = await sh("npm run test:integration");
      if (integration.exitCode !== 0) {
        await sh("git reset --hard HEAD~1");  // on retire la branche fautive
        r.status = "integration_failed";
      }
    }
  }

  return results;
}

// orchestration/budget.ts
// Trois budgets indépendants, paliers de dégradation, arrêt sauvegardé.

export type Budget = {
  maxIterations: number;
  maxTokens: number;
  maxWallClockMs: number;
};

export type Usage = {
  iterations: number;
  tokens: number;
  startedAt: number;
};

export type Level = "nominal" | "warn" | "degraded" | "exhausted";

/** Le palier le plus contraignant des trois l'emporte. */
export function levelOf(usage: Usage, budget: Budget): Level {
  const ratios = [
    usage.iterations / budget.maxIterations,
    usage.tokens / budget.maxTokens,
    (Date.now() - usage.startedAt) / budget.maxWallClockMs,
  ];
  const worst = Math.max(...ratios);

  if (worst >= 1) return "exhausted";
  if (worst >= 0.75) return "degraded";
  if (worst >= 0.5) return "warn";
  return "nominal";
}

// ---------------------------------------------------------------------------
// orchestration/loop.ts — la boucle, avec sortie garantie

export async function orchestrate(tasks: TaskContract[], budget: Budget) {
  const usage: Usage = { iterations: 0, tokens: 0, startedAt: Date.now() };
  const waves = planWaves(tasks);
  let model = "modele-principal";

  for (const wave of waves) {
    for (const task of wave) {
      const level = levelOf(usage, budget);

      if (level === "exhausted") {
        // Arrêt propre : l'état doit être repris demain sans archéologie.
        await saveCheckpoint({ usage, lastTask: task.id, reason: "budget épuisé" });
        return { status: "stopped" as const, usage };
      }

      if (level === "degraded" && model !== "modele-economique") {
        model = "modele-economique";
        await compactContext();  // résumé de l'historique, on repart plus léger
        log.warn("Budget à 75 % : bascule sur le modèle économique.");
      }

      if (level === "warn") log.warn("Budget à 50 %.", { usage });

      const before = usage.tokens;
      const result = await delegate(task, agentWith(model));

      usage.iterations += 1;
      usage.tokens += result.tokensUsed;

      // Signal précoce : un coût par tâche qui s'envole annonce un contexte malade.
      const perTask = usage.tokens - before;
      if (perTask > 3 * averageOf(history.map((h) => h.tokens))) {
        log.warn(`Tâche ${task.id} : coût anormal (${perTask} jetons). Contexte à inspecter.`);
      }

      history.push({ task: task.id, tokens: perTask, status: result.status });
    }
  }

  return { status: "completed" as const, usage, costPerAcceptedTask: costPerAccepted(history) };
}

/** Le seul indicateur qui compte : dépense rapportée au travail réellement accepté. */
function costPerAccepted(history: Entry[]) {
  const accepted = history.filter((h) => h.status === "done").length;
  const spent = history.reduce((sum, h) => sum + h.tokens, 0);
  return accepted ? spent / accepted : Infinity;
}

/** Un arrêt sans point de reprise coûte plus cher que le dépassement évité. */
async function saveCheckpoint(data: Checkpoint) {
  await writeFile(".orchestration/checkpoint.json", JSON.stringify(data, null, 2));
  await sh("git add -A && git commit -m 'wip: arrêt sur budget' --no-verify");
}

// src/lib/utils/cn.ts
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// src/components/ui/button.tsx
import * as React from "react";
import { cn } from "@/lib/utils/cn";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "primary" | "secondary" | "outline";
  size?: "sm" | "md" | "lg";
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = "primary", size = "md", ...props }, ref) => {
    const baseStyles = "inline-flex items-center justify-center rounded-md font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none";
    const variantStyles = {
      primary: "bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500",
      secondary: "bg-gray-100 text-gray-900 hover:bg-gray-200 focus:ring-gray-500",
      outline: "border border-gray-300 bg-transparent hover:bg-gray-50 focus:ring-gray-500",
    };
