// src/lib/query-keys.ts
// Les clés sont centralisées et typées. Dispersées en chaînes littérales,
// elles divergent, et une invalidation cesse silencieusement de fonctionner.

export const keys = {
  invoices: {
    all: ["invoices"] as const,
    // La clé contient TOUT ce qui fait varier le résultat.
    list: (f: InvoiceFilters) => ["invoices", "list", f] as const,
    detail: (id: string) => ["invoices", "detail", id] as const,
  },
  customers: {
    all: ["customers"] as const,
    detail: (id: string) => ["customers", "detail", id] as const,
  },
} as const;

// ---------------------------------------------------------------------------
// src/lib/query-client.ts — les durées sont des décisions, pas des défauts.

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // Laissé à 0 (le défaut), on revalide à chaque montage : le cache ne sert à rien.
      staleTime: 30_000,
      gcTime: 5 * 60_000,
      // Ne pas réessayer sur une erreur du client : la requête est fautive,
      // la rejouer trois fois ne la rendra pas valide.
      retry: (failureCount, error) =>
        error instanceof ApiError && error.status < 500 ? false : failureCount < 2,
      refetchOnWindowFocus: true,
    },
  },
});

// ---------------------------------------------------------------------------
// src/hooks/use-invoices.ts — validation à l'exécution à la frontière.

export function useInvoices(filters: InvoiceFilters) {
  return useQuery({
    queryKey: keys.invoices.list(filters),
    queryFn: async ({ signal }) => {
      const res = await apiFetch("/invoices", { params: filters, signal });
      // Le type déclaré ne vérifie RIEN à l'exécution. Le schéma, si.
      return InvoiceListResponse.parse(res);
    },
    // Pagination : conserve la page précédente pendant le chargement de la suivante.
    // Sans cela, la liste disparaît à chaque changement de page.
    placeholderData: keepPreviousData,
    // Un solde se revalide plus souvent qu'un catalogue : décision MÉTIER.
    staleTime: filters.status === "draft" ? 0 : 60_000,
  });
}

// ---------------------------------------------------------------------------
// Mutation : invalidation déclarée, et mise à jour optimiste réversible.

export function useVoidInvoice() {
  const qc = useQueryClient();

  return useMutation({
    mutationFn: (id: string) => apiFetch(`/invoices/${id}/void`, { method: "POST" }),

    async onMutate(id) {
      // Annuler les requêtes en vol : sinon une réponse ancienne écrase
      // la mise à jour optimiste quelques millisecondes plus tard.
      await qc.cancelQueries({ queryKey: keys.invoices.detail(id) });

      const previous = qc.getQueryData(keys.invoices.detail(id));
      qc.setQueryData(keys.invoices.detail(id), (old) => ({ ...old, status: "void" }));
      return { previous };   // renvoyé au contexte pour pouvoir annuler
    },

    onError(_err, id, ctx) {
      // Retour à l'état antérieur : une mise à jour optimiste sans annulation
      // laisse une interface qui ment après un échec.
      if (ctx?.previous) qc.setQueryData(keys.invoices.detail(id), ctx.previous);
    },

    onSettled(_data, _err, id) {
      // On DÉCLARE ce qui est périmé. On ne recharge pas les écrans à la main.
      qc.invalidateQueries({ queryKey: keys.invoices.detail(id) });
      qc.invalidateQueries({ queryKey: keys.invoices.all });
    },
  });
}

// ---------------------------------------------------------------------------
// Les quatre états, distingués. Les confondre produit un écran clignotant.

export function InvoiceList({ filters }: { filters: InvoiceFilters }) {
  const { data, error, isPending, isFetching } = useInvoices(filters);

  // 1. Premier chargement : aucune donnée à montrer.
  if (isPending) return <InvoiceListSkeleton />;

  // 2. Erreur SANS donnée : état d'erreur plein écran.
  if (error && !data) return <ErrorState error={error} />;

  return (
    <>
      {/* 3. Erreur AVEC données : on garde l'affichage et on signale. */}
      {error && <StaleBanner message="Données peut-être périmées. Reconnexion…" />}
      {/* 4. Revalidation en arrière-plan : indicateur discret, pas de squelette. */}
      {isFetching && <SubtleSpinner />}
      <ul>{data!.items.map((i) => <InvoiceRow key={i.id} invoice={i} />)}</ul>
    </>
  );
}

// src/lib/schemas/user-schema.ts
// Le schéma Zod est LA source de vérité : les types TypeScript en sont dérivés,
// et le MÊME schéma est réutilisé côté serveur. Une seule définition, zéro dérive.
import { z } from "zod";

export const userSchema = z.object({
  fullName: z
    .string()
    .trim()
    .min(2, "Le nom doit contenir au moins 2 caractères")
    .max(80, "Le nom ne peut pas dépasser 80 caractères"),
  email: z.string().trim().toLowerCase().email("Adresse email invalide"),
  role: z.enum(["apprenant", "formateur", "admin"], {
    errorMap: () => ({ message: "Sélectionne un rôle valide" }),
  }),
  age: z.coerce
    .number({ invalid_type_error: "L'âge doit être un nombre" })
    .int("L'âge doit être un entier")
    .min(16, "Tu dois avoir au moins 16 ans")
    .max(120, "Âge invalide"),
  bio: z.string().max(500, "500 caractères maximum").optional(),
});

// z.infer dérive le type depuis le schéma : jamais d'interface écrite à la main
// en parallèle, qui finirait fatalement par diverger de la validation.
export type UserFormValues = z.infer<typeof userSchema>;

// src/components/forms/user-form.tsx
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { usersApi } from "@/lib/api/users";
import { queryKeys } from "@/lib/query-keys";
import { userSchema, type UserFormValues } from "@/lib/schemas/user-schema";

export function UserForm({ onSuccess }: { onSuccess?: () => void }) {
  const queryClient = useQueryClient();

  const {
    register,
    handleSubmit,
    reset,
    setError,
    formState: { errors, isSubmitting, isValid },
  } = useForm<UserFormValues>({
    resolver: zodResolver(userSchema),
    // mode "onBlur" : on ne crie pas pendant la frappe, on valide à la sortie
    // du champ. "onChange" est agressif, "onSubmit" découvre tout trop tard.
    mode: "onBlur",
    reValidateMode: "onChange",
    defaultValues: { fullName: "", email: "", role: "apprenant", age: 18, bio: "" },
  });

  const createUser = useMutation({
    mutationFn: usersApi.create,
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: queryKeys.users.all });
      reset();
      onSuccess?.();
    },
    onError: (error: unknown) => {
      // Les erreurs métier renvoyées par le serveur sont réinjectées dans le
      // formulaire, sur le champ concerné quand c'est possible.
      const message = error instanceof Error ? error.message : "Erreur inconnue";
      setError("root.serverError", { type: "server", message });
    },
  });

  // isSubmitting est géré par RHF et reste vrai tant que la promesse de
  // onSubmit n'est pas résolue : c'est notre garde anti double-soumission.
  const onSubmit = handleSubmit(async (values) => {
    await createUser.mutateAsync(values);
  });

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-4">
      <div>
        <label htmlFor="fullName" className="block text-sm font-medium">
          Nom complet
        </label>
        <input
          id="fullName"
          {...register("fullName")}
          // aria-invalid signale l'erreur aux technologies d'assistance,
          // pas seulement aux yeux du voyant.
          aria-invalid={errors.fullName ? "true" : "false"}
          aria-describedby={errors.fullName ? "fullName-error" : undefined}
          className="mt-1 w-full rounded-md border px-3 py-2"
        />
        {errors.fullName && (
          // role="alert" force l'annonce immédiate du message par le lecteur d'écran.
          <p id="fullName-error" role="alert" className="mt-1 text-sm text-red-600">
            {errors.fullName.message}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="email" className="block text-sm font-medium">
          Email
        </label>
        <input
          id="email"
          type="email"
          {...register("email")}
          aria-invalid={errors.email ? "true" : "false"}
          aria-describedby={errors.email ? "email-error" : undefined}
          className="mt-1 w-full rounded-md border px-3 py-2"
        />
        {errors.email && (
          <p id="email-error" role="alert" className="mt-1 text-sm text-red-600">
            {errors.email.message}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="age" className="block text-sm font-medium">
          Âge
        </label>
        <input
          id="age"
          type="number"
          {...register("age")}
          aria-invalid={errors.age ? "true" : "false"}
          aria-describedby={errors.age ? "age-error" : undefined}
          className="mt-1 w-full rounded-md border px-3 py-2"
        />
        {errors.age && (
          <p id="age-error" role="alert" className="mt-1 text-sm text-red-600">
            {errors.age.message}
          </p>
        )}
      </div>

      {errors.root?.serverError && (
        <p role="alert" className="text-sm text-red-600">
          {errors.root.serverError.message}
        </p>
      )}

      <button
        type="submit"
        // Double protection : l'attribut disabled empêche le clic, et
        // isSubmitting empêche l'appel réseau même si l'événement passe.
        disabled={isSubmitting || !isValid}
        className="rounded-md bg-primary px-4 py-2 text-white disabled:opacity-50"
      >
        {isSubmitting ? "Enregistrement…" : "Créer l'utilisateur"}
      </button>
    </form>
  );
}

// src/server/routes/users.ts
// RAPPEL CAPITAL : la validation côté client est une COMMODITÉ D'INTERFACE,
// jamais une sécurité. N'importe qui peut appeler l'API avec curl. Le MÊME
// schéma Zod revalide donc la charge utile côté serveur — une seule source de
// vérité, deux points d'application.
import { userSchema } from "@/lib/schemas/user-schema";

export async function createUserHandler(request: Request) {
  const parsed = userSchema.safeParse(await request.json());

  if (!parsed.success) {
    return Response.json(
      {
        error: {
          code: "VALIDATION_ERROR",
          message: "Données utilisateur invalides",
          details: parsed.error.flatten().fieldErrors,
        },
      },
      { status: 422 },
    );
  }

  // Au-delà de cette ligne, parsed.data est typé UserFormValues et digne de confiance.
  const user = await db.users.create(parsed.data);
  return Response.json(user, { status: 201 });
}

/* src/styles/tokens.css — les décisions visuelles, en un seul endroit */
:root {
  /* ── Gris : 10 paliers. C'est 90 % de l'interface réelle, on les soigne. ── */
  --grey-50: #f8fafc;
  --grey-100: #f1f5f9;
  --grey-200: #e2e8f0;
  --grey-300: #cbd5e1;
  --grey-400: #94a3b8;
  --grey-500: #64748b;
  --grey-600: #475569;
  --grey-700: #334155;
  --grey-800: #1e293b;
  --grey-900: #0f172a;

  /* ── Primaire : 6 nuances utilisables ── */
  --primary-100: #dbeafe;
  --primary-300: #93c5fd;
  --primary-500: #3b82f6;
  --primary-600: #2563eb; /* contraste 4.6:1 sur blanc → AA pour le texte */
  --primary-700: #1d4ed8;
  --primary-900: #1e3a8a;

  /* ── Rôles sémantiques : c'est CE QUE les composants consomment ──
     Nommer par le rôle et non par la valeur permet de rebasculer tout le
     thème en réassignant ces lignes, sans toucher à un seul composant. */
  --color-surface: #ffffff;
  --color-surface-raised: var(--grey-50);
  --color-border: var(--grey-200);
  --color-text: var(--grey-900); /* 17.9:1 sur blanc  → AAA */
  --color-text-muted: var(--grey-600); /*  7.4:1 sur blanc  → AA  */
  --color-text-subtle: var(--grey-500); /*  4.8:1 sur blanc  → AA  (limite) */
  --color-accent: var(--primary-600);
}

/* Le mode sombre RÉASSIGNE les rôles : zéro composant dupliqué. */
.dark {
  --color-surface: var(--grey-900);
  --color-surface-raised: var(--grey-800);
  --color-border: var(--grey-700);
  --color-text: var(--grey-50);
  --color-text-muted: var(--grey-300);
  --color-text-subtle: var(--grey-400);
  --color-accent: var(--primary-300); /* éclairci : le 600 ne passe pas sur fond sombre */
}

