// src/components/ui/course-card.tsx
// Une carte HIÉRARCHISÉE. Avant d'écrire la moindre classe, on répond à la
// question de establish-visual-hierarchy : 1) le titre, 2) la progression,
// 3) les métadonnées. Tout le reste est dé-emphasé.
interface CourseCardProps {
  title: string;
  category: string;
  progressPercent: number;
  lessonCount: number;
  updatedAt: string;
}

export function CourseCard({
  title,
  category,
  progressPercent,
  lessonCount,
  updatedAt,
}: CourseCardProps) {
  return (
    <article className="rounded-lg border border-border bg-surface p-6">
      {/* Niveau 3 — métadonnée : petite, grise, légère. Présente mais discrète. */}
      <p className="text-caption font-medium uppercase tracking-wide text-ink-muted">{category}</p>

      {/* Niveau 1 — l'élément qui doit être lu EN PREMIER.
          Il gagne par la taille ET la graisse ET le contraste maximal.
          Les trois leviers vont dans le même sens : c'est ce qui crée
          une hiérarchie lisible plutôt qu'un simple « c'est plus gros ». */}
      <h3 className="mt-2 text-section font-semibold text-ink">{title}</h3>

      {/* Niveau 2 — la progression. Elle ne rivalise pas avec le titre :
          taille du corps, graisse moyenne. L'espace au-dessus (mt-4) fait
          autant pour sa visibilité qu'un changement de taille. */}
      <div className="mt-4">
        <div className="flex items-baseline justify-between">
          <span className="text-body font-medium text-ink">{progressPercent}% terminé</span>
          <span className="text-caption text-ink-muted">{lessonCount} leçons</span>
        </div>
        <div
          className="mt-2 h-2 overflow-hidden rounded-full bg-border"
          role="progressbar"
          aria-valuenow={progressPercent}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-label={`Progression du cours ${title}`}
        >
          <div className="h-full bg-accent" style={{ width: `${progressPercent}%` }} />
        </div>
      </div>

      {/* Niveau 3 — dé-emphase assumée. text-ink-muted = 7.4:1, donc AA :
          discret NE VEUT PAS DIRE illisible. Le piège classique est de
          descendre à un gris 400 (2.8:1) qui échoue au test de contraste. */}
      <p className="mt-4 text-caption text-ink-muted">Mis à jour le {updatedAt}</p>
    </article>
  );
}

// src/components/ui/button.tsx
// La hiérarchie d'actions encodée dans le TYPE : un variant invalide ne
// compile pas. La règle de design devient une garantie du compilateur.
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center rounded-md font-medium transition-colors " +
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent " +
    "disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      variant: {
        // PRIMAIRE — un seul par écran. Fond plein, contraste maximal.
        primary: "bg-accent text-white hover:bg-primary-700",
        // SECONDAIRE — contour. Visible, mais ne rivalise pas.
        secondary: "border border-border bg-surface text-ink hover:bg-surface-raised",
        // TERTIAIRE — texte seul. Pour les actions de sortie (Annuler, Retour).
        ghost: "text-ink-muted hover:bg-surface-raised hover:text-ink",
        // DESTRUCTIF — rouge, et JAMAIS le primaire par défaut d'un écran.
        destructive: "bg-red-600 text-white hover:bg-red-700",
      },
      size: {
        sm: "h-8 px-3 text-caption",
        md: "h-10 px-4 text-body",
        lg: "h-12 px-6 text-lead",
      },
    },
    defaultVariants: { variant: "secondary", size: "md" },
    // Le défaut est "secondary", pas "primary" : il faut un acte VOLONTAIRE
    // pour créer un bouton primaire. Le défaut protège la règle.
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {}

export function Button({ className, variant, size, ...props }: ButtonProps) {
  return <button className={cn(buttonVariants({ variant, size }), className)} {...props} />;
}

