// src/components/forms/field.tsx
// La loi de proximité appliquée à un champ de formulaire.
export function Field({
  label,
  htmlFor,
  hint,
  error,
  children,
}: {
  label: string;
  htmlFor: string;
  hint?: string;
  error?: string;
  children: React.ReactNode;
}) {
  return (
    // space-y-1.5 À L'INTÉRIEUR du groupe (étiquette + champ + aide).
    // L'espace ENTRE deux champs est géré par le parent, à space-y-6.
    // Rapport 1:4 — c'est CE RAPPORT, pas les valeurs absolues, qui rend
    // le formulaire lisible. À écarts égaux, le regard ne peut plus
    // associer une étiquette à son champ.
    <div className="space-y-1.5">
      <label htmlFor={htmlFor} className="block text-caption font-medium text-ink">
        {label}
      </label>
      {children}
      {hint && !error && <p className="text-caption text-ink-muted">{hint}</p>}
      {error && (
        <p role="alert" className="text-caption text-red-600">
          {error}
        </p>
      )}
    </div>
  );
}

