        ))}
      </ul>
    </section>
  );
}

// ════════ 1. COMPOSITION PLUTÔT QUE PROPS BOOLÉENNES ════════

// ❌ AVANT — l'explosion combinatoire : 5 booléens = 32 états possibles,
// dont une poignée seulement a du sens. Chaque besoin ajoute un booléen.
interface BadPanelProps {
  title: string;
  isCompact?: boolean;
  hasHeaderAction?: boolean;
  hasFooter?: boolean;
  isCollapsible?: boolean;
  showBorder?: boolean;
}

// ✅ APRÈS — composition. L'appelant assemble ce dont il a besoin ;
// le composant n'a connaissance d'aucun cas particulier.
import { createContext, useContext, useId } from "react";

type PanelDensity = "comfortable" | "compact"; // union discriminée, pas un booléen

const PanelContext = createContext<{ density: PanelDensity; titleId: string } | null>(null);

function usePanelContext() {
  const ctx = useContext(PanelContext);
  if (!ctx) throw new Error("Les sous-composants Panel.* doivent être utilisés dans <Panel>");
  return ctx;
}

export function Panel({
  density = "comfortable",
  children,
}: {
  density?: PanelDensity;
  children: React.ReactNode;
}) {
  const titleId = useId();
  return (
    <PanelContext.Provider value={{ density, titleId }}>
      <section aria-labelledby={titleId} className="rounded-lg border border-border bg-surface">
        {children}
      </section>
    </PanelContext.Provider>
  );
}

Panel.Header = function PanelHeader({ children }: { children: React.ReactNode }) {
  const { density, titleId } = usePanelContext();
  return (
    <header
      id={titleId}
      className={density === "compact" ? "px-4 py-3" : "px-6 py-5"}
      // Pas de bordure basse : l'espacement sépare déjà (eliminate-visual-clutter).
    >
      {children}
    </header>
  );
};

Panel.Body = function PanelBody({ children }: { children: React.ReactNode }) {
  const { density } = usePanelContext();
  return <div className={density === "compact" ? "px-4 pb-4" : "px-6 pb-6"}>{children}</div>;
};

Panel.Footer = function PanelFooter({ children }: { children: React.ReactNode }) {
  const { density } = usePanelContext();
  return (
    <footer className={`flex justify-end gap-2 ${density === "compact" ? "p-4" : "p-6"}`}>
      {children}
    </footer>
  );
};

// Usage : le pied de page existe parce qu'on l'écrit, pas parce qu'un
// booléen vaut true. Aucun cas non prévu n'est possible.
//
//   <Panel density="compact">
//     <Panel.Header>Mes rendus</Panel.Header>
//     <Panel.Body>…</Panel.Body>
//     <Panel.Footer><Button variant="primary">Envoyer</Button></Panel.Footer>
//   </Panel>

// ════════ 2. DÉRIVER PLUTÔT QUE SYNCHRONISER ════════

// ❌ ANTI-PATTERN — la copie de prop dans un état, resynchronisée par effet.
function BadFilteredList({ items, query }: { items: Item[]; query: string }) {
  const [filtered, setFiltered] = useState<Item[]>([]);
  useEffect(() => {
    setFiltered(items.filter((i) => i.title.includes(query)));
  }, [items, query]);
  // Trois défauts : (1) le premier rendu affiche une liste VIDE puis se
  // corrige — un flash visible ; (2) `filtered` est une deuxième source de
  // vérité qui peut diverger ; (3) un rendu supplémentaire à chaque frappe.
  return <List items={filtered} />;
}

// ✅ CORRECT — on CALCULE pendant le rendu. Pas d'état, pas d'effet,
// pas de rendu intermédiaire incorrect. Toujours juste, par construction.
function FilteredList({ items, query }: { items: Item[]; query: string }) {
  const filtered = items.filter((i) => i.title.includes(query));
  return <List items={filtered} />;
}

// ✅ Avec useMemo UNIQUEMENT si le calcul est réellement coûteux et mesuré.
// useMemo optimise un calcul ; il ne STOCKE pas un état. La nuance est
// essentielle : on peut retirer le useMemo sans changer le comportement.
function ExpensiveFilteredList({ items, query }: { items: Item[]; query: string }) {
  const filtered = useMemo(
    () => items.filter((i) => expensiveMatch(i, query)),
    [items, query],
  );
  return <List items={filtered} />;
}

// ✅ useEffect LÉGITIME : synchronisation avec un système EXTÉRIEUR à React.
// Le commentaire nomme explicitement ce système — exigé en revue.
function useOnlineStatus() {
  const [isOnline, setIsOnline] = useState(() => navigator.onLine);
  useEffect(() => {
    // Système extérieur : les événements réseau du navigateur.
    const on = () => setIsOnline(true);
    const off = () => setIsOnline(false);
    window.addEventListener("online", on);
    window.addEventListener("offline", off);
    return () => {
      window.removeEventListener("online", on);
      window.removeEventListener("offline", off);
    };
  }, []);
  return isOnline;
}

// ════════ 3. VIEW TRANSITIONS SOBRES, AVEC REPLI ════════

// src/hooks/use-view-transition.ts
export function useViewTransition() {
  return useCallback((update: () => void) => {
    const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    // Deux conditions de repli. Dans les deux cas, la mise à jour est
    // appliquée IMMÉDIATEMENT : le contenu ne doit jamais disparaître
    // parce qu'une animation n'est pas disponible.
    if (prefersReducedMotion || !("startViewTransition" in document)) {
      update();
      return;
    }

    document.startViewTransition(update);
  }, []);
}

// Usage dans un composant
function TabPanel() {
  const [tab, setTab] = useState<"cours" | "rendus">("cours");
  const transition = useViewTransition();

  return (
    <>
      <Button variant="ghost" onClick={() => transition(() => setTab("rendus"))}>
        Mes rendus
      </Button>
      {/* view-transition-name doit être UNIQUE à l'écran, sinon la
          transition est silencieusement ignorée par le navigateur. */}
      <div style={{ viewTransitionName: "tab-content" }}>
        {tab === "cours" ? <CoursList /> : <SubmissionsList />}
      </div>
    </>
  );
}

/* src/styles/transitions.css — sobriété : 180ms, opacité seule.
   Pas de glissement, pas de rebond : l'animation sert la compréhension
   du changement, elle n'est pas un effet. */
::view-transition-old(tab-content),
::view-transition-new(tab-content) {
  animation-duration: 180ms;
  animation-timing-function: ease;
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }
}

// src/modules/users/users.schemas.ts
import { z } from 'zod';

// Schéma d'entrée pour la création d'un utilisateur
export const CreateUserInputSchema = z.object({
  email: z.string().email('Email invalide').max(255),
  password: z.string().min(8, 'Le mot de passe doit contenir au moins 8 caractères').regex(/[A-Z]/, 'Doit contenir une majuscule'),
  firstName: z.string().min(1).max(50),
  lastName: z.string().min(1).max(50),
});

// Schéma d'entrée pour la mise à jour d'un utilisateur
export const UpdateUserInputSchema = z.object({
  firstName: z.string().min(1).max(50).optional(),
  lastName: z.string().min(1).max(50).optional(),
  email: z.string().email().max(255).optional(),
});

// Schéma de sortie (sériezation sécurisée) - On ne renvoie JAMAIS le mot de passe
export const UserOutputSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  firstName: z.string(),
  lastName: z.string(),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date(),
});

// Types TypeScript dérivés automatiquement
export type CreateUserInput = z.infer<typeof CreateUserInputSchema>;
export type UpdateUserInput = z.infer<typeof UpdateUserInputSchema>;
export type UserOutput = z.infer<typeof UserOutputSchema>;

// src/modules/users/users.service.ts
import { PrismaClient } from '@prisma/client';
import { CreateUserInput, UpdateUserInput, UserOutput } from './users.schemas';
import { UserNotFoundError, EmailAlreadyExistsError } from '../../utils/error';

// Injection de dépendance : le service reçoit l'instance Prisma
export class UserService {
  constructor(private readonly prisma: PrismaClient) {}

  async createUser(input: CreateUserInput): Promise<UserOutput> {
    // Vérifier si l'email existe déjà
    const existingUser = await this.prisma.user.findUnique({
      where: { email: input.email },
    });

    if (existingUser) {
      throw new EmailAlreadyExistsError('Cet email est déjà utilisé');
    }

    // Hachage du mot de passe (simulé ici, utiliser bcrypt en prod)
    const hashedPassword = await this.hashPassword(input.password);

    const user = await this.prisma.user.create({
      data: {
        email: input.email,
        password: hashedPassword,
        firstName: input.firstName,
        lastName: input.lastName,
      },
      // On ne sélectionne que les champs nécessaires pour la sortie
      select: {
        id: true,
        email: true,
        firstName: true,
        lastName: true,
        createdAt: true,
        updatedAt: true,
      },
    });

    return user as UserOutput;
  }

  async getUserById(id: string): Promise<UserOutput> {
    const user = await this.prisma.user.findUnique({
      where: { id },
      select: {
        id: true,
        email: true,
        firstName: true,
        lastName: true,
        createdAt: true,
        updatedAt: true,
      },
    });

    if (!user) {
      throw new UserNotFoundError('Utilisateur non trouvé');
    }

    return user as UserOutput;
  }

  async updateUser(id: string, input: UpdateUserInput): Promise<UserOutput> {
    const user = await this.prisma.user.update({
      where: { id },
      data: input,
      select: {
        id: true,
        email: true,
        firstName: true,
        lastName: true,
        createdAt: true,
        updatedAt: true,
      },
    });

    return user as UserOutput;
  }

  private async hashPassword(password: string): Promise<string> {
    // Implémentation réelle avec bcrypt
    // const bcrypt = require('bcrypt');
    // return bcrypt.hash(password, 10);
    return 'hashed_' + password; // Simulation
  }
}

// src/modules/users/users.routes.ts
import { FastifyInstance } from 'fastify';
import { UserService } from './users.service';
import { CreateUserInputSchema, UpdateUserInputSchema, UserOutputSchema } from './users.schemas';
import { prisma } from '../../lib/prisma';

// Injection de dépendance dans la route
const userService = new UserService(prisma);

export async function userRoutes(app: FastifyInstance) {
  // POST /users
  app.post('/users', {
    schema: {
      body: CreateUserInputSchema,
      response: {
        201: UserOutputSchema,
      },
    },
  }, async (request, reply) => {
    try {
      const user = await userService.createUser(request.body);
      return reply.status(201).send(user);
    } catch (error) {
      // La gestion des erreurs est centralisée, mais on peut logger ici si nécessaire
      throw error;
    }
  });

  // GET /users/:id
  app.get('/users/:id', {
    schema: {
      params: z.object({ id: z.string().uuid() }),
      response: {
        200: UserOutputSchema,
      },
    },
  }, async (request, reply) => {
    const user = await userService.getUserById(request.params.id);
    return reply.status(200).send(user);
  });

  // PATCH /users/:id
  app.patch('/users/:id', {
    schema: {
      params: z.object({ id: z.string().uuid() }),
      body: UpdateUserInputSchema,
      response: {
        200: UserOutputSchema,
      },
    },
  }, async (request, reply) => {
    const user = await userService.updateUser(request.params.id, request.body);
    return reply.status(200).send(user);
  });
}

chapters.architecturalPatterns:
Pattern de validation centralisée :
1. **Schémas d'entrée** : Définis dans `*.schemas.ts`. Utilisés dans la configuration de la route Fastify (`schema: { body: ..., query: ..., params: ... }`).
2. **Schémas de sortie** : Définis dans `*.schemas.ts`. Utilisés dans la configuration de la réponse Fastify (`schema: { response: { 200: ... } }`).
3. **Transformation des données** : Utiliser `.transform()` ou `.pipe()` dans Zod pour modifier les données avant la validation ou après.
4. **Erreurs de validation** : Fastify intercepte les erreurs de validation Zod et les convertit en réponses HTTP 400 avec un format standardisé.

Exemple de structure de schéma :
```typescript
// users.schemas.ts
export const UserQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(10),
  search: z.string().optional(),
});

export type UserQuery = z.infer<typeof UserQuerySchema>;
```

