// src/schemas/invoice.ts
// Le schéma est la source de vérité : types, validation d'entrée ET
// sérialisation de sortie en dérivent. Aucune duplication.

import { z } from "zod";

export const InvoiceStatus = z.enum(["draft", "sent", "paid", "void"]);

export const CreateInvoiceBody = z.object({
  customerId: z.string().uuid("Identifiant client invalide."),
  currency: z.enum(["EUR", "USD", "XOF"]),
  lines: z
    .array(
      z.object({
        label: z.string().min(1).max(200),
        // Montants en centimes : jamais de flottant pour de l'argent.
        unitAmount: z.number().int().nonnegative(),
        quantity: z.number().int().positive().max(10_000),
      }),
    )
    .min(1, "Une facture contient au moins une ligne.")
    .max(200),
  dueAt: z.coerce.date().refine((d) => d.getTime() > Date.now(), {
    message: "L'échéance doit être postérieure à maintenant.",
  }),
});

export const InvoiceParams = z.object({ id: z.string().uuid() });

export const InvoiceQuery = z.object({
  status: InvoiceStatus.optional(),
  // Les query strings sont des chaînes : coerce, puis bornes strictes.
  limit: z.coerce.number().int().min(1).max(100).default(20),
  cursor: z.string().optional(),
});

// Schéma de SORTIE : liste blanche explicite. Ce qui n'y figure pas ne sort pas.
export const InvoiceReply = z.object({
  id: z.string().uuid(),
  customerId: z.string().uuid(),
  currency: z.enum(["EUR", "USD", "XOF"]),
  status: InvoiceStatus,
  totalAmount: z.number().int(),
  dueAt: z.date(),
  createdAt: z.date(),
});

export type CreateInvoiceBody = z.infer<typeof CreateInvoiceBody>;
export type InvoiceReply = z.infer<typeof InvoiceReply>;

// ---------------------------------------------------------------------------
// src/routes/invoices.ts — Fastify + type provider Zod : types inférés de bout en bout.

import type { FastifyPluginAsyncZod } from "fastify-type-provider-zod";

export const invoiceRoutes: FastifyPluginAsyncZod = async (app) => {
  app.post(
    "/invoices",
    {
      schema: {
        body: CreateInvoiceBody,
        response: {
          201: InvoiceReply,
          422: z.object({ code: z.literal("VALIDATION_ERROR"), issues: z.array(z.unknown()) }),
        },
      },
    },
    async (req, reply) => {
      // req.body est typé CreateInvoiceBody, déjà validé : aucun cast, aucun `any`.
      const total = req.body.lines.reduce((s, l) => s + l.unitAmount * l.quantity, 0);

      const invoice = await app.invoices.create({ ...req.body, totalAmount: total });

      // invoice vient de la base et contient internalNotes, customerEmail, etc.
      // Le schéma de réponse les retire : la fuite est impossible par construction.
      return reply.code(201).send(invoice);
    },
  );

  app.get(
    "/invoices/:id",
    { schema: { params: InvoiceParams, response: { 200: InvoiceReply } } },
    async (req) => app.invoices.byId(req.params.id),
  );
};

// ---------------------------------------------------------------------------
// src/app.ts — erreurs de validation normalisées, une fois pour toutes.

import { serializerCompiler, validatorCompiler, hasZodFastifySchemaValidationErrors }
  from "fastify-type-provider-zod";

export function buildApp() {
  const app = Fastify({ logger: true }).withTypeProvider<ZodTypeProvider>();

  app.setValidatorCompiler(validatorCompiler);
  app.setSerializerCompiler(serializerCompiler);

  app.setErrorHandler((err, req, reply) => {
    if (hasZodFastifySchemaValidationErrors(err)) {
      // 422 et non 400 : la requête est bien formée, son contenu est invalide.
      return reply.code(422).send({
        code: "VALIDATION_ERROR",
        issues: err.validation.map((v) => ({ path: v.instancePath, message: v.message })),
      });
    }
    // Une erreur de sérialisation est un bug serveur, jamais une erreur client.
    req.log.error({ err }, "Erreur non gérée");
    return reply.code(500).send({ code: "INTERNAL_ERROR" });
  });

  return app;
}

// prisma/schema.prisma
// Les contraintes vivent dans le schéma, pas dans l'espoir que le code les respecte.

model Customer {
  id        String    @id @default(uuid())
  email     String    @unique
  name      String
  invoices  Invoice[]
  createdAt DateTime  @default(now())

  @@index([createdAt])
}

model Invoice {
  id          String        @id @default(uuid())
  customer    Customer      @relation(fields: [customerId], references: [id], onDelete: Restrict)
  customerId  String
  currency    Currency
  status      InvoiceStatus @default(draft)
  totalAmount Int                                  // centimes, jamais de Float
  dueAt       DateTime
  lines       InvoiceLine[]
  createdAt   DateTime      @default(now())
  updatedAt   DateTime      @updatedAt

  // Un client ne peut pas avoir deux brouillons de même échéance.
  @@unique([customerId, dueAt, status], name: "uniq_draft_per_due_date")
  @@index([status, dueAt])
}

model InvoiceLine {
  id         String  @id @default(uuid())
  invoice    Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)
  invoiceId  String
  label      String
  unitAmount Int
  quantity   Int

  @@index([invoiceId])
}

enum InvoiceStatus { draft sent paid void }
enum Currency      { EUR USD XOF }

// ---------------------------------------------------------------------------
// src/repositories/invoice.repository.ts
// La frontière transactionnelle est explicite et ne contient aucun appel réseau.

import { Prisma, type PrismaClient } from "@prisma/client";

export class InvoiceRepository {
  constructor(private readonly db: PrismaClient) {}

  /** Création atomique : la facture et ses lignes existent ensemble ou pas du tout. */
  async createWithLines(input: CreateInvoiceBody & { totalAmount: number }) {
    try {
      return await this.db.$transaction(async (tx) => {
        const invoice = await tx.invoice.create({
          data: {
            customerId: input.customerId,
            currency: input.currency,
            totalAmount: input.totalAmount,
            dueAt: input.dueAt,
            lines: { createMany: { data: input.lines } },
          },
          include: { lines: true },
        });

        await tx.auditLog.create({
          data: { entity: "invoice", entityId: invoice.id, action: "created" },
        });

        return invoice;
      }, {
        // Bornes explicites : une transaction qui traîne bloque les autres.
        maxWait: 2_000,
        timeout: 5_000,
      });
    } catch (e) {
      // Les erreurs Prisma connues deviennent des erreurs métier, pas des 500.
      if (e instanceof Prisma.PrismaClientKnownRequestError) {
        if (e.code === "P2002") throw new ConflictError("Brouillon déjà existant pour cette échéance.");
        if (e.code === "P2003") throw new NotFoundError("Client inconnu.");
      }
      throw e;
    }
  }

  /** Pagination par curseur : stable même si des lignes sont insérées entre deux pages. */
  async list(params: { status?: InvoiceStatus; limit: number; cursor?: string }) {
    const rows = await this.db.invoice.findMany({
      where: params.status ? { status: params.status } : undefined,
      take: params.limit + 1,                        // +1 pour savoir s'il y a une suite
      ...(params.cursor ? { cursor: { id: params.cursor }, skip: 1 } : {}),
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],  // tri total, sinon curseur instable
    });

    const hasMore = rows.length > params.limit;
    return { items: hasMore ? rows.slice(0, -1) : rows, nextCursor: hasMore ? rows.at(-2)!.id : null };
  }
}

// ---------------------------------------------------------------------------
// Effet externe APRÈS commit : on ne tient pas un verrou pendant un appel réseau.

async function createInvoiceAndNotify(input: CreateInvoiceBody) {
  const invoice = await repo.createWithLines({ ...input, totalAmount: total(input) });
  await mailer.send(invoice.customerId, "invoice.created", invoice.id);  // hors transaction
  return invoice;
}

// src/plugins/auth.ts
// Authentification : établir l'identité. Rien d'autre.

import fp from "fastify-plugin";
import { z } from "zod";

const AccessClaims = z.object({
  sub: z.string().uuid(),
  role: z.enum(["customer", "staff", "admin"]),
  tokenType: z.literal("access"),   // empêche d'utiliser un refresh comme access
});

export default fp(async (app) => {
  app.decorateRequest("user", null);

  app.decorate("authenticate", async (req, reply) => {
    const header = req.headers.authorization;
    if (!header?.startsWith("Bearer ")) {
      return reply.code(401).send({ code: "UNAUTHENTICATED" });
    }
    try {
      const raw = await app.jwt.verify(header.slice(7));
      req.user = AccessClaims.parse(raw);   // les claims aussi sont validés
    } catch {
      return reply.code(401).send({ code: "INVALID_TOKEN" });
    }
  });

  // Autorisation grossière : filtre d'entrée, insuffisant à lui seul.
  app.decorate("requireRole", (...roles: Role[]) => async (req, reply) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return reply.code(403).send({ code: "FORBIDDEN" });
    }
  });
});

// ---------------------------------------------------------------------------
// src/routes/invoices.ts — autorisation fine, au plus près de la donnée.

app.get(
  "/invoices/:id",
  {
    schema: { params: InvoiceParams, response: { 200: InvoiceReply } },
    onRequest: [app.authenticate],
  },
  async (req, reply) => {
    const { id } = req.params;

    // Le filtre de propriété fait partie de la REQUÊTE, pas d'un test après coup.
    // Un `findUnique({ where: { id } })` suivi d'un `if` laisse passer les erreurs
    // de rafraîchissement et les accès concurrents.
    const invoice =
      req.user.role === "admin"
        ? await db.invoice.findUnique({ where: { id } })
        : await db.invoice.findFirst({ where: { id, customerId: req.user.sub } });

    // 404 et non 403 : on ne confirme pas l'existence d'un identifiant inconnu.
    if (!invoice) return reply.code(404).send({ code: "NOT_FOUND" });

    return invoice;
  },
);

// ---------------------------------------------------------------------------
// src/routes/auth.ts — rotation du jeton de renouvellement.

app.post("/auth/refresh", async (req, reply) => {
  const presented = req.cookies["rt"];
  if (!presented) return reply.code(401).send({ code: "NO_REFRESH_TOKEN" });

  const stored = await db.refreshToken.findUnique({ where: { hash: sha256(presented) } });

  // Jeton déjà consommé = vol probable : on révoque toute la famille.
  if (stored?.usedAt) {
    await db.refreshToken.updateMany({
      where: { familyId: stored.familyId, revokedAt: null },
      data: { revokedAt: new Date() },
    });
    req.log.warn({ userId: stored.userId }, "Réutilisation de jeton détectée : famille révoquée.");
    return reply.code(401).send({ code: "TOKEN_REUSE_DETECTED" });
  }

  if (!stored || stored.revokedAt || stored.expiresAt < new Date()) {
    return reply.code(401).send({ code: "INVALID_REFRESH_TOKEN" });
  }

  await db.refreshToken.update({ where: { id: stored.id }, data: { usedAt: new Date() } });
  const next = await issueRefreshToken(stored.userId, stored.familyId);

  return reply
    .setCookie("rt", next, { httpOnly: true, secure: true, sameSite: "strict", path: "/auth" })
    .send({ accessToken: await issueAccessToken(stored.userId) });
});

// ---------------------------------------------------------------------------
// src/app.ts — durcissement du transport.

await app.register(helmet);
await app.register(rateLimit, {
  max: 100,
  timeWindow: "1 minute",
  // Par identité quand elle est connue : sinon un NAT d'entreprise partage un quota.
  keyGenerator: (req) => req.user?.sub ?? req.ip,
});
app.server.requestTimeout = 10_000;
// bodyLimit est fixé à la construction : Fastify({ bodyLimit: 1_048_576 })

// src/errors.ts
// Une hiérarchie minuscule suffit, à condition qu'elle soit respectée partout.

export abstract class AppError extends Error {
  abstract readonly statusCode: number;
  abstract readonly code: string;
  /** Contexte structuré joint au journal, jamais renvoyé au client. */
  constructor(message: string, readonly context: Record<string, unknown> = {}) {
    super(message);
    this.name = new.target.name;
  }
}

export class NotFoundError extends AppError {
  readonly statusCode = 404;
  readonly code = "NOT_FOUND";
}
export class ConflictError extends AppError {
  readonly statusCode = 409;
  readonly code = "CONFLICT";
}

// ---------------------------------------------------------------------------
// src/app.ts — journaliseur structuré, secrets filtrés à la source.

const app = Fastify({
  // Un identifiant par requête, repris de l'amont s'il existe.
  genReqId: (req) => (req.headers["x-request-id"] as string) ?? randomUUID(),
  logger: {
    level: process.env.LOG_LEVEL ?? "info",
    redact: {
      paths: [
        "req.headers.authorization",
        "req.headers.cookie",
        'req.body.password',
        'req.body.cardNumber',
      ],
      censor: "[masqué]",
    },
    serializers: {
      // Par défaut Pino journalise l'intégralité de la requête : trop, et risqué.
      req: (req) => ({ method: req.method, url: req.url, route: req.routeOptions?.url }),
      res: (res) => ({ statusCode: res.statusCode }),
    },
  },
});

// Contexte attaché une fois, présent sur toutes les lignes de la requête.
app.addHook("onRequest", async (req) => {
  req.log = req.log.child({ requestId: req.id, userId: req.user?.sub });
});

// Mesure de durée : un champ numérique, agrégeable, pas une phrase.
app.addHook("onResponse", async (req, reply) => {
  req.log.info(
    { durationMs: Math.round(reply.elapsedTime), statusCode: reply.statusCode, outcome: "completed" },
    "requête traitée",
  );
});

// ---------------------------------------------------------------------------
// Gestionnaire d'erreurs : la frontière entre attendu et inattendu.

app.setErrorHandler((err, req, reply) => {
  if (err instanceof AppError) {
    // Attendue : pas de pile, pas d'alerte, niveau proportionné.
    req.log.info({ code: err.code, ...err.context }, err.message);
    return reply.code(err.statusCode).send({ code: err.code, message: err.message });
  }

  if (hasZodFastifySchemaValidationErrors(err)) {
    req.log.info({ code: "VALIDATION_ERROR" }, "entrée invalide");
    return reply.code(422).send({ code: "VALIDATION_ERROR", issues: err.validation });
  }

  // Inattendue : pile complète côté journal, message opaque côté client.
  // Le requestId est renvoyé pour que le support fasse le lien sans exposer l'interne.
  req.log.error({ err, stack: err.stack }, "erreur non gérée");
  return reply.code(500).send({ code: "INTERNAL_ERROR", requestId: req.id });
});

// ---------------------------------------------------------------------------
// Propagation vers les appels sortants : la corrélation ne s'arrête pas à la frontière.

export async function callPaymentService(req: FastifyRequest, payload: PaymentPayload) {
  const started = performance.now();
  try {
    const res = await fetch(`${PAYMENT_URL}/charge`, {
      method: "POST",
      headers: { "content-type": "application/json", "x-request-id": String(req.id) },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(5_000),
    });
    req.log.info(
      { dependency: "payment", status: res.status, durationMs: Math.round(performance.now() - started) },
      "appel sortant",
    );
    if (!res.ok) throw new ConflictError("Paiement refusé.", { status: res.status });
    return res.json();
  } catch (e) {
    req.log.error({ dependency: "payment", err: e }, "appel sortant en échec");
    throw e;
  }
}

