// test/helpers.ts — isolation par transaction annulée.

export function withRollback(fn: (tx: Prisma.TransactionClient) => Promise<void>) {
  return async () => {
    await db
      .$transaction(async (tx) => {
        await fn(tx);
        throw new RollbackSignal();   // on annule systématiquement
      })
      .catch((e) => {
        if (!(e instanceof RollbackSignal)) throw e;
      });
  };
}

