// tokens/primitives.ts
// Couche 1 : valeurs brutes. Aucun composant ne les référence jamais directement.
// La palette est dérivée dans un espace perceptuellement uniforme : à palier égal,
// le contraste est comparable d'une teinte à l'autre — ce que lighten/darken en RVB
// ne garantit jamais.

import { formatHex, oklch } from "culori";

/** Clarté par palier, fixée une fois. C'est elle qui porte la garantie de contraste. */
const LIGHTNESS = {
  50: 0.97, 100: 0.94, 200: 0.88, 300: 0.8, 400: 0.7,
  500: 0.62, 600: 0.54, 700: 0.46, 800: 0.37, 900: 0.26,
} as const;

function ramp(hue: number, chroma: number) {
  return Object.fromEntries(
    Object.entries(LIGHTNESS).map(([step, l]) => [
      step,
      // La chroma se réduit aux extrémités : sinon les paliers clairs et sombres
      // paraissent délavés ou fluorescents.
      formatHex(oklch({ mode: "oklch", l, c: chroma * (1 - Math.abs(l - 0.6) * 0.9), h: hue })),
    ]),
  ) as Record<keyof typeof LIGHTNESS, string>;
}

export const primitives = {
  gray: ramp(255, 0.02),
  blue: ramp(255, 0.15),
  red: ramp(25, 0.17),
  green: ramp(150, 0.14),
} as const;

// ---------------------------------------------------------------------------
// tokens/semantic.ts
// Couche 2 : des RÔLES. Le nom ne contient jamais de couleur ni de valeur,
// sinon il devient faux au premier changement de thème ou de marque.

export const semantic = {
  light: {
    "surface-base": primitives.gray[50],
    "surface-raised": "#ffffff",
    "text-primary": primitives.gray[900],
    "text-muted": primitives.gray[700],
    "border-subtle": primitives.gray[200],
    "action-primary": primitives.blue[600],
    "action-danger": primitives.red[600],
  },
  dark: {
    "surface-base": primitives.gray[900],
    "surface-raised": primitives.gray[800],
    "text-primary": primitives.gray[50],
    "text-muted": primitives.gray[300],   // éclairci : le 700 échoue sur fond sombre
    "border-subtle": primitives.gray[800],
    "action-primary": primitives.blue[400],
    "action-danger": primitives.red[400],
  },
} as const;

