// tokens/scales.ts — échelles choisies, pas calculées par une formule.

/** Dense en bas (texte et annotations), clairsemée en haut (titres).
 *  Une progression géométrique pure laisse un trou là où se trouvent les besoins. */
export const fontSize = {
