// scripts/check-contrast.ts — la conformité est VÉRIFIÉE, pas supposée.

import { wcagContrast, parse } from "culori";

const PAIRS: Array<[string, string, number]> = [
  ["text-primary", "surface-base", 4.5],
  ["text-muted", "surface-base", 4.5],
  ["text-primary", "surface-raised", 4.5],
  ["action-primary", "surface-base", 3.0],   // non textuel : 3:1 suffit
];

let failed = false;
for (const theme of ["light", "dark"] as const) {
  for (const [fg, bg, min] of PAIRS) {
    const ratio = wcagContrast(parse(semantic[theme][fg])!, parse(semantic[theme][bg])!);
    if (ratio < min) {
      console.error(`✗ ${theme} : ${fg} sur ${bg} = ${ratio.toFixed(2)}:1 (minimum ${min})`);
      failed = true;
    }
  }
}
process.exit(failed ? 1 : 0);   // bloquant : un avertissement serait ignoré

// src/components/ui/text.tsx
// La hiérarchie typographique est ENCODÉE dans des rôles, pas improvisée par écran.
// Chaque rôle fixe taille, poids, hauteur de ligne et couleur ensemble —
// c'est leur combinaison qui crée le niveau, pas la taille seule.

import { cva, type VariantProps } from "class-variance-authority";

const text = cva("", {
  variants: {
    role: {
      // Titres : serrés, sombres, rares.
      pageTitle: "text-4xl font-semibold leading-tight text-[--text-primary]",
      sectionTitle: "text-2xl font-semibold leading-snug text-[--text-primary]",
      cardTitle: "text-lg font-medium leading-snug text-[--text-primary]",
      // Corps : aéré, lisible.
      body: "text-base font-normal leading-normal text-[--text-primary]",
      // Secondaire : ATTÉNUÉ. C'est ce niveau qui fait émerger les autres.
      secondary: "text-sm font-normal leading-normal text-[--text-muted]",
      caption: "text-xs font-normal leading-normal text-[--text-muted]",
    },
  },
  defaultVariants: { role: "body" },
});

type TextProps = VariantProps<typeof text> & {
  as?: "p" | "span" | "h1" | "h2" | "h3" | "div";
} & React.HTMLAttributes<HTMLElement>;

export function Text({ as: Tag = "p", role, className, ...props }: TextProps) {
  // Le rôle VISUEL est découplé de la balise SÉMANTIQUE : un titre de carte
  // peut être un h3 sans que la hiérarchie des titres du document soit cassée.
  return <Tag className={twMerge(text({ role }), className)} {...props} />;
}

// ---------------------------------------------------------------------------
// src/components/ui/stack.tsx
// L'espacement devient une décision de composition, prise par le parent.
// Tant que chaque composant porte ses propres marges, les espaces s'additionnent
// de façon imprévisible et personne ne sait d'où vient un écart de 28 px.

const stack = cva("flex", {
  variants: {
    direction: { vertical: "flex-col", horizontal: "flex-row items-center" },
    // Rapport 1:3 entre l'intérieur et l'extérieur d'un groupe.
    gap: { tight: "gap-2", normal: "gap-4", loose: "gap-6", section: "gap-12" },
  },
  defaultVariants: { direction: "vertical", gap: "normal" },
});

export function Stack({ direction, gap, className, ...p }: StackProps) {
  return <div className={twMerge(stack({ direction, gap }), className)} {...p} />;
}

// ---------------------------------------------------------------------------
// Avant / après sur un écran réel : aucune couleur ajoutée, aucune bordure.

// ✗ Tout au même niveau : gras partout, bordures partout, trois boutons pleins.
