// ---------------------------------------------------------------------------
// scripts/check-hierarchy.ts — quelques règles mécanisables.

const RULES = [
  { name: "plus d'un bouton primaire par écran",
    find: (ast) => countJsx(ast, "Button", { variant: "primary" }) > 1 },
