// ✗ Le réflexe coûteux : réimplémenter un bouton.
// Manquent : la touche Espace, le type submit, l'état disabled, le mode contraste
// élevé, l'intégration au formulaire. On les découvrira un par un, en production.
<div role="button" tabIndex={0} onClick={save} onKeyDown={(e) => e.key === "Enter" && save()}>
  Enregistrer
</div>

// ✓ Le natif apporte tout cela gratuitement.
<button type="submit" onClick={save}>Enregistrer</button>

// ---------------------------------------------------------------------------
// src/components/ui/field.tsx
// Le lien libellé/champ/erreur est STRUCTUREL. Une erreur affichée en rouge
// à côté d'un champ n'existe pas pour un lecteur d'écran si rien ne les relie.

export function Field({ label, error, hint, children }: FieldProps) {
  const id = useId();
  const errorId = `${id}-error`;
  const hintId = `${id}-hint`;

  return (
    <div className="flex flex-col gap-1">
      {/* htmlFor : agrandit aussi la zone cliquable, bénéfice universel. */}
      <label htmlFor={id} className="text-sm font-medium text-[--text-primary]">
        {label}
      </label>

      {cloneElement(children, {
        id,
        // L'état d'erreur passe par les DEUX canaux : bordure rouge ET aria-invalid.
        "aria-invalid": error ? true : undefined,
        // describedby relie le champ à son aide ET à son erreur, dans cet ordre.
        "aria-describedby": [hint && hintId, error && errorId].filter(Boolean).join(" ") || undefined,
      })}

      {hint && <p id={hintId} className="text-xs text-[--text-muted]">{hint}</p>}

      {/* role="alert" annonce l'erreur dès son apparition, sans déplacer le focus. */}
      {error && (
        <p id={errorId} role="alert" className="text-xs text-[--action-danger]">
          {error}
        </p>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// src/components/ui/dialog.tsx — le retour du focus est la partie oubliée.

export function Dialog({ open, onClose, title, children }: DialogProps) {
  const ref = useRef<HTMLDialogElement>(null);
  const opener = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    if (open) {
      // Mémoriser QUI a ouvert, avant que le focus ne bouge.
      opener.current = document.activeElement as HTMLElement;
      // showModal apporte nativement : piège de focus, inertie de l'arrière-plan,
      // fermeture par Échap, rôle dialog. Tout cela serait à réécrire sinon.
      el.showModal();
    } else if (el.open) {
      el.close();
      // Sans cette ligne, l'utilisateur au clavier repart du haut du document.
      opener.current?.focus();
    }
  }, [open]);

  return (
    <dialog ref={ref} onClose={onClose} aria-labelledby="dlg-title" className="...">
      <h2 id="dlg-title">{title}</h2>
      {children}
    </dialog>
  );
}

// ---------------------------------------------------------------------------
// src/components/ui/tabs.tsx — un seul arrêt de tabulation pour tout le groupe.

export function Tabs({ tabs, value, onChange }: TabsProps) {
  function onKeyDown(e: React.KeyboardEvent) {
    const i = tabs.findIndex((t) => t.id === value);
    const next = { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: tabs.length - 1 }[e.key];
    if (next === undefined) return;
    e.preventDefault();
    onChange(tabs[(next + tabs.length) % tabs.length].id);
  }

  return (
    <div role="tablist" onKeyDown={onKeyDown}>
      {tabs.map((t) => (
        <button
          key={t.id}
          role="tab"
          aria-selected={t.id === value}
          aria-controls={`panel-${t.id}`}
          // Un seul tabIndex à 0 : la tabulation traverse le groupe d'un coup.
          tabIndex={t.id === value ? 0 : -1}
          onClick={() => onChange(t.id)}
        >
          {t.label}
        </button>
      ))}
    </div>
  );
}

