// src/components/ui/button.tsx
// cva encode les combinaisons LÉGALES. L'illégal devient inexprimable.

import { cva, type VariantProps } from "class-variance-authority";
import { twMerge } from "tailwind-merge";
import { Slot } from "@radix-ui/react-slot";

const button = cva(
  // Base commune : ce qui est vrai pour TOUS les boutons, y compris l'accessibilité.
  [
    "inline-flex items-center justify-center gap-2 rounded-md font-medium",
    "transition-colors select-none",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[--focus-ring] focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-50",
  ],
  {
    variants: {
      variant: {
        primary: "bg-[--action-primary] text-white hover:bg-[--action-primary-hover]",
        secondary: "bg-[--surface-raised] text-[--text-primary] hover:bg-[--border-subtle]",
        ghost: "bg-transparent text-[--text-primary] hover:bg-[--surface-raised]",
        danger: "bg-red-600 text-white hover:bg-red-700",
      },
      size: {
        sm: "h-8 px-3 text-sm",
        md: "h-10 px-4 text-sm",
        lg: "h-12 px-6 text-base",
      },
      fullWidth: { true: "w-full", false: "" },
    },
    // Les exceptions légitimes sont DÉCLARÉES, pas bricolées dans le JSX.
    compoundVariants: [
      { variant: "ghost", size: "sm", class: "px-2" },
      { variant: "danger", size: "lg", class: "font-semibold" },
    ],
    defaultVariants: { variant: "primary", size: "md", fullWidth: false },
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof button> {
  /** Rend l'élément enfant à la place du <button> : <Button asChild><Link/></Button> */
  asChild?: boolean;
}

export function Button({ className, variant, size, fullWidth, asChild, ...props }: ButtonProps) {
  const Comp = asChild ? Slot : "button";
