// src/auth/verify.ts
// La vérification impose ses attentes. Elle ne lit pas dans le jeton
// ce qu'elle est censée contrôler.

import { createPublicKey } from "node:crypto";
import { jwtVerify } from "jose";
import { z } from "zod";

const AccessClaims = z.object({
  sub: z.string().uuid(),
  role: z.enum(["customer", "staff", "admin"]),
  // Sans ce champ, un jeton de renouvellement passe pour un jeton d'accès.
  typ: z.literal("access"),
  // Version de session : permet la révocation malgré l'absence d'état.
  sv: z.number().int(),
});

export async function verifyAccessToken(token: string) {
  const { payload } = await jwtVerify(token, publicKey, {
    algorithms: ["RS256"],              // IMPOSÉ ici, jamais lu dans l'en-tête du jeton
    issuer: "https://auth.example",     // sinon un jeton voisin est accepté
    audience: "api.example",
    clockTolerance: 5,
  });

  const claims = AccessClaims.parse(payload);

  // Compensation de l'absence d'état : une lecture en cache, O(1).
  const current = await kv.get(`sv:${claims.sub}`);
  if (current !== null && Number(current) !== claims.sv) {
    throw new UnauthorizedError("Session révoquée.");
  }
  return claims;
}

/** Révocation immédiate de toutes les sessions d'un compte. */
export async function revokeSessions(userId: string) {
  await kv.incr(`sv:${userId}`);        // tous les jetons émis deviennent caducs
}

