export function setSessionCookies(reply: FastifyReply, access: string, refresh: string) {
  reply.setCookie("at", access, {
    httpOnly: true,            // hors de portée d'un script injecté
    secure: true,
    sameSite: "lax",
    path: "/",
    maxAge: 600,               // 10 min : fenêtre d'exploitation réduite
  });
  reply.setCookie("rt", refresh, {
    httpOnly: true,
    secure: true,
    sameSite: "strict",        // le renouvellement ne part jamais en contexte tiers
    path: "/auth/refresh",     // portée minimale : envoyé à UNE seule route
    maxAge: 2_592_000,
  });
}

// Contrepartie du cookie : la requête intersite. Jeton à double soumission.
app.addHook("onRequest", async (req, reply) => {
  if (!MUTATING.has(req.method)) return;
  const header = req.headers["x-csrf-token"];
  const cookie = req.cookies["csrf"];
  // Comparaison à temps constant : une comparaison naïve fuit par la durée.
  if (!header || !cookie || !timingSafeEqualStr(String(header), cookie)) {
    return reply.code(403).send({ code: "CSRF_FAILED" });
  }
});

