// src/db/with-identity.ts — l'identité est posée sur la CONNEXION, dans la transaction.

export async function withIdentity<T>(userId: string, fn: (tx: Tx) => Promise<T>) {
  return db.$transaction(async (tx) => {
    // set_config local : la valeur retombe à la fin de la transaction.
    // Indispensable avec un pool : sinon la connexion repart avec l'identité du précédent.
    await tx.$executeRaw`SELECT set_config('app.current_user_id', ${userId}, true)`;
    return fn(tx);
  });
}

