// src/config/secrets.ts
// Lire une fois au démarrage rend toute rotation équivalente à un redéploiement.
// Un cache court transforme la rotation en opération routinière.

import { GetSecretValueCommand, SecretsManagerClient } from "@aws-sdk/client-secrets-manager";

const client = new SecretsManagerClient({});
const cache = new Map<string, { value: string; expiresAt: number }>();
const TTL_MS = 300_000;   // 5 min : une rotation se propage sans redéploiement

export async function getSecret(name: string): Promise<string> {
  const hit = cache.get(name);
  if (hit && hit.expiresAt > Date.now()) return hit.value;

  try {
    const res = await client.send(new GetSecretValueCommand({ SecretId: name }));
    const value = res.SecretString!;
    cache.set(name, { value, expiresAt: Date.now() + TTL_MS });
    return value;
  } catch (e) {
    // Repli sur la valeur expirée : une panne du gestionnaire ne doit pas
    // provoquer une panne applicative.
    if (hit) {
      logger.warn({ name, err: e }, "Gestionnaire de secrets injoignable, valeur en cache.");
      return hit.value;
    }
    throw e;
  }
}

// ---------------------------------------------------------------------------
// Rotation sans interruption : la fenêtre d'acceptation double est obligatoire.

export async function verifyWebhookSignature(payload: string, signature: string) {
  // Pendant la rotation, les deux secrets sont valides. Sans cette fenêtre,
  // les requêtes en vol au moment de la bascule échouent toutes.
  const [current, previous] = await Promise.all([
    getSecret("webhook/signing-key"),
    getSecret("webhook/signing-key-previous").catch(() => null),
  ]);

  const expected = (key: string) => createHmac("sha256", key).update(payload).digest();
  const given = Buffer.from(signature, "hex");

  // Comparaison à temps constant, sur les deux clés.
  return (
    timingSafeEqualSafe(given, expected(current)) ||
    (previous !== null && timingSafeEqualSafe(given, expected(previous)))
  );
}

