import { Prisma } from "@prisma/client";

const SORTABLE = { createdAt: "created_at", dueAt: "due_at", amount: "total_amount" } as const;

export async function listInvoices(customerId: string, sortBy: string, dir: string) {
  // Les IDENTIFIANTS ne sont pas paramétrables : liste blanche, pas échappement.
  const column = SORTABLE[sortBy as keyof typeof SORTABLE];
  if (!column) throw new ValidationError(`Tri non autorisé : ${sortBy}`);
  const direction = dir === "asc" ? Prisma.sql`ASC` : Prisma.sql`DESC`;

  return db.$queryRaw`
    SELECT id, total_amount, due_at
    FROM invoices
    WHERE customer_id = ${customerId}
    ORDER BY ${Prisma.raw(column)} ${direction}
    LIMIT 100
  `;
}

