import { resolve, sep } from "node:path";

const UPLOAD_ROOT = resolve("/var/app/uploads");

export function safeUploadPath(userFilename: string): string {
  // On résout d'abord : toutes les remontées et tous les encodages sont réduits.
  const candidate = resolve(UPLOAD_ROOT, userFilename);

  // Puis on vérifie le confinement. Le séparateur final évite que
  // /var/app/uploads-public soit accepté comme préfixe valide.
  if (!candidate.startsWith(UPLOAD_ROOT + sep)) {
    throw new ValidationError("Chemin hors du répertoire autorisé.");
  }
  return candidate;
}

