export function parseWebhook(raw: string) {
  let data: unknown;
  try {
    data = JSON.parse(raw);        // produit uniquement des valeurs inertes
  } catch {
    throw new ValidationError("Charge utile illisible.");
  }

  // La forme n'est pas supposée : elle est prouvée.
  return WebhookPayload.parse(data);
}

// Protection contre la pollution de prototype sur les objets dynamiques.
const FORBIDDEN = new Set(["__proto__", "constructor", "prototype"]);

export function mergeSafe(target: Record<string, unknown>, patch: Record<string, unknown>) {
  for (const [k, v] of Object.entries(patch)) {
    if (FORBIDDEN.has(k)) continue;   // sinon on modifie Object.prototype global
    target[k] = v;
  }
  return target;
}

// docs/threat-model/invoices.md — le modèle est versionné AVEC le code.
//
// ## Frontière : navigateur ╎ API /invoices
// | STRIDE | Menace                                   | Décision   | Mise en œuvre        |
// |--------|------------------------------------------|------------|----------------------|
// | S      | Rejeu d'un jeton volé                    | atténuer   | accès 10 min + rotation |
// | T      | Modification du montant côté client      | atténuer   | montant recalculé serveur |
