/** Invalide toutes les sessions émises avant maintenant, sans toucher à la base de jetons. */
export async function revokeAllSessionsGlobally(reason: string) {
  // Les jetons d'accès portent un "iat" : on déplace la frontière de validité.
  await kv.set("auth:minIssuedAt", Date.now());
  await db.refreshToken.updateMany({ where: { revokedAt: null }, data: { revokedAt: new Date() } });
  await auditLog.create({ data: { action: "security.global_revocation", reason } });
}

/** Mode lecture seule : préserve le service tout en stoppant les écritures malveillantes. */
export async function enableReadOnlyMode(reason: string) {
