}

// Vérifié à chaque requête mutante, coût négligeable.
app.addHook("onRequest", async (req, reply) => {
  if (MUTATING.has(req.method) && (await kv.get("app:readOnly"))) {
    return reply.code(503).send({ code: "READ_ONLY_MODE" });
  }
  const claims = req.user;
  if (claims && claims.iat * 1000 < Number(await kv.get("auth:minIssuedAt"))) {
    return reply.code(401).send({ code: "SESSION_REVOKED" });
  }
});

