// src/agent/memory.ts
// Deux vitesses. Le noyau ne sort jamais : c'est lui qui gouverne les décisions,
// et c'est exactement ce qu'une troncature par ancienneté supprime en premier.

interface Memory {
  /** Stable, rappelé à chaque tour. Ne défile jamais. */
  core: { objective: string; constraints: string[]; decisions: string[] };
  /** Défile. Résumé quand la place manque, jamais tronqué sèchement. */
  recent: Turn[];
  /** Résumés des tours sortis de la fenêtre. */
  summaries: string[];
}

export async function compact(memory: Memory, budget: TokenBudget): Promise<Memory> {
  const used = countTokens(render(memory));
  if (used <= budget.contextTokens) return memory;

  // On résume la MOITIÉ LA PLUS ANCIENNE de l'historique, pas la totalité :
  // les tours récents portent le fil de la tâche en cours.
  const cutoff = Math.floor(memory.recent.length / 2);
  const toSummarize = memory.recent.slice(0, cutoff);

  const summary = await llm.complete({
    model: SMALL_MODEL,              // résumer ne demande pas le gros modèle
    system:
      "Résume ces tours en préservant IMPÉRATIVEMENT : décisions prises, " +
      "contraintes découvertes, erreurs rencontrées et leur cause. " +
      "Omets les formulations, les salutations et les raisonnements intermédiaires.",
    user: render(toSummarize),
    temperature: 0,
  });

  return { ...memory, recent: memory.recent.slice(cutoff), summaries: [...memory.summaries, summary.text] };
}

// ---------------------------------------------------------------------------
// src/agent/loop.ts — la boucle est encadrée par trois bornes indépendantes.

export async function runAgent(task: string, ctx: Ctx) {
  const budget = new Budget({ maxTurns: 12, maxCostEur: 0.5, maxSeconds: 120 });
  let memory = initMemory(task);
  const recentActions: string[] = [];

  while (true) {
    // Borne 1 et 2 : tours et dépense. Vérifiées AVANT l'appel, pas après.
    const stop = budget.shouldStop();
    if (stop) return finalize(memory, { reason: stop });

    memory = await compact(memory, budget);

    const step = await llm.complete({
      system: SYSTEM,
      user: render(memory),
      tools: TOOLS,
      temperature: 0.2,
    });
    budget.record(step.usage);

    if (step.finishReason === "final") return finalize(memory, { reason: "completed" });

    // Borne 3 : non-progression. Une boucle qui répète la même action
    // n'échouera pas d'elle-même — elle consommera jusqu'à épuisement.
    const signature = `${step.tool.name}:${stableHash(step.tool.args)}`;
    recentActions.push(signature);
    if (occurrences(recentActions.slice(-4), signature) >= 3) {
      logger.warn({ signature }, "Boucle détectée : même action répétée sans progrès.");
      return finalize(memory, { reason: "no_progress" });
    }

    const observation = await executeTool(step.tool, ctx);

    // L'observation est tronquée AVANT d'entrer en mémoire : une sortie d'outil
    // de 50 000 caractères évince tout le reste du contexte.
    memory.recent.push({
      thought: step.thought,
      action: step.tool,
      observation: truncate(observation, 2_000),
    });

    // Une décision explicite rejoint le noyau : elle ne doit plus jamais sortir.
    if (step.decision) memory.core.decisions.push(step.decision);
  }
}

// ---------------------------------------------------------------------------
// src/agent/budget.ts — le budget est un garde-fou de sûreté, pas une économie.

export class Budget {
  private turns = 0;
  private costEur = 0;
  private readonly startedAt = Date.now();

  constructor(private readonly limits: Limits) {}

  record(usage: Usage) {
    this.turns++;
    this.costEur += usage.promptTokens * PRICE.in + usage.completionTokens * PRICE.out;
  }

  shouldStop(): StopReason | null {
    if (this.turns >= this.limits.maxTurns) return "max_turns";
    if (this.costEur >= this.limits.maxCostEur) return "max_cost";
    if (Date.now() - this.startedAt > this.limits.maxSeconds * 1000) return "timeout";
    return null;
  }
}

// ---------------------------------------------------------------------------
// La trace de raisonnement sert au DIAGNOSTIC : on retrouve le tour de divergence.

export function explainRun(memory: Memory) {
  return memory.recent.map((t, i) => ({
    turn: i,
    thought: t.thought.slice(0, 200),
    action: t.action.name,
    observationOk: !t.observation.startsWith("ERREUR"),
  }));
}

// src/agent/tools/definition.ts
// Deux sources d'arguments, strictement séparées. C'est la décision structurante.

export interface ToolDef<A extends z.ZodTypeAny> {
  name: string;
  /** Vue par le modèle. Ne contient QUE ce qui relève de l'intention. */
  schema: A;
  description: string;
  risk: "low" | "medium" | "high";
  idempotent: boolean;
  /** ctx vient du contexte AUTHENTIFIÉ : le modèle ne peut pas l'influencer. */
  execute: (args: z.infer<A>, ctx: AuthContext) => Promise<unknown>;
}

export const createInvoice: ToolDef<typeof CreateInvoiceArgs> = {
  name: "create_invoice",

  // La description est le SEUL élément sur lequel le modèle fonde son choix.
  description: [
    "Crée une facture en brouillon pour un client existant.",
    "QUAND L'UTILISER : l'utilisateur demande explicitement l'établissement d'une facture",
    "et a fourni le client ainsi qu'au moins une ligne.",
    "QUAND NE PAS L'UTILISER : pour consulter une facture existante (utiliser find_invoice),",
    "pour estimer un montant sans créer de document, ou si le client n'est pas identifié",
    "— demander alors la précision à l'utilisateur.",
    "RENVOIE : l'identifiant de la facture et son montant total calculé côté serveur.",
  ].join("\n"),

  risk: "medium",
  idempotent: true,

  schema: z.object({
    customerId: z.string().uuid().describe("Identifiant du client, obtenu via find_customer."),
    lines: z
      .array(
        z.object({
          label: z.string().min(1).max(200),
          unitAmount: z.number().int().nonnegative().describe("En centimes, jamais en euros."),
          quantity: z.number().int().positive().max(1000),
        }),
      )
      .min(1)
      .max(50),
    // Clé fournie par la boucle, stable pour une même intention : rend la reprise sûre.
    idempotencyKey: z.string().uuid(),
  }),
  // Absents du schéma, donc non manipulables : tenantId, userId, role.

  async execute(args, ctx) {
    // Le périmètre vient du contexte. Un identifiant bien formé ne prouve rien
    // sur le droit d'y accéder.
    const customer = await db.customer.findFirst({
      where: { id: args.customerId, tenantId: ctx.tenantId },
    });
    if (!customer) throw new ToolError("Client introuvable dans votre périmètre.");

    // Idempotence : la reprise après un délai dépassé ne doit pas créer un doublon.
    const existing = await db.invoice.findUnique({ where: { idempotencyKey: args.idempotencyKey } });
    if (existing) return { id: existing.id, totalAmount: existing.totalAmount, replayed: true };

    // Le total est recalculé côté serveur : il n'est pas dans le schéma d'entrée.
    const totalAmount = args.lines.reduce((s, l) => s + l.unitAmount * l.quantity, 0);
    const invoice = await db.invoice.create({
      data: { ...args, tenantId: ctx.tenantId, createdBy: ctx.userId, totalAmount },
    });
    return { id: invoice.id, totalAmount };
  },
};

// ---------------------------------------------------------------------------
// src/agent/dispatch.ts — validation, autorisation, exécution, erreur lisible.

export async function dispatch(call: ModelToolCall, ctx: AuthContext) {
  const tool = REGISTRY.get(call.name);
  if (!tool) {
    // Erreur rédigée pour le modèle : elle doit permettre une correction.
    return toolError(`Outil inconnu : ${call.name}. Disponibles : ${[...REGISTRY.keys()].join(", ")}.`);
  }

  const parsed = tool.schema.safeParse(call.args);
  if (!parsed.success) {
    // On renvoie le champ ET la valeur reçue : sans elles, le modèle répète à l'identique.
    const issues = parsed.error.issues
      .map((i) => `${i.path.join(".")} : ${i.message} (reçu : ${JSON.stringify(get(call.args, i.path))})`)
      .join(" ; ");
    return toolError(`Arguments invalides pour ${tool.name}. ${issues}`);
  }

  // Les actions à risque élevé passent par un humain, quelle que soit la demande.
  if (tool.risk === "high") {
    return { status: "awaiting_confirmation", tool: tool.name, args: parsed.data };
  }

  try {
    const result = await withTimeout(tool.execute(parsed.data, ctx), 15_000);
    audit.record({ tool: tool.name, userId: ctx.userId, args: redact(parsed.data) });
    return { status: "ok", result };
  } catch (e) {
    if (e instanceof ToolError) return toolError(e.message);   // métier, corrigeable
    logger.error({ err: e, tool: tool.name }, "échec d'outil");
    // Un bug interne ne doit pas inviter le modèle à réessayer indéfiniment.
    return toolError("Erreur interne. N'insiste pas, signale-le à l'utilisateur.");
  }
}

// src/rag/chunking.ts
// Le découpage structurel bat le découpage à taille fixe, et de loin.

interface Chunk {
  text: string;
  /** En-tête de contexte : sans lui, « il doit être recalculé » n'a aucun sens isolé. */
  breadcrumb: string;
  docId: string;
  sourceUrl: string;
  position: number;
}

export function chunkMarkdown(doc: SourceDoc, maxChars = 1200, overlap = 150): Chunk[] {
  const sections = splitByHeadings(doc.markdown);   // on suit la STRUCTURE
  const chunks: Chunk[] = [];

  for (const section of sections) {
    const breadcrumb = [doc.title, ...section.headingPath].join(" > ");

    if (section.text.length <= maxChars) {
      chunks.push({ text: `${breadcrumb}\n\n${section.text}`, breadcrumb, ...meta(doc) });
      continue;
    }
    // Section trop longue : on coupe aux limites de PHRASE, avec recouvrement.
    for (const part of splitSentencesWithOverlap(section.text, maxChars, overlap)) {
      chunks.push({ text: `${breadcrumb}\n\n${part}`, breadcrumb, ...meta(doc) });
    }
  }
  return chunks;
}

// ---------------------------------------------------------------------------
// src/rag/retrieve.ts — hybride puis réordonnancement.

export async function retrieve(question: string, k = 5) {
  // La réécriture résout les références : « et pour celui-là ? » est inrécupérable.
  const query = await rewriteQuery(question);

  const [dense, lexical] = await Promise.all([
    vectorStore.search(await embed(query), { limit: 30 }),
    // BM25 retrouve « ERR_CONN_4042 » que la recherche dense manque toujours.
    bm25.search(query, { limit: 30 }),
  ]);

  // Fusion par rang réciproque : pas de score à normaliser entre deux échelles.
  const fused = reciprocalRankFusion([dense, lexical], { k: 60 }).slice(0, 30);

  // Le cross-encoder lit question ET passage ensemble : bien plus précis,
  // mais trop coûteux pour être appliqué à l'index entier.
  const ranked = await reranker.score(query, fused);
  return ranked.filter((r) => r.score >= 0.25).slice(0, k);
}

