// src/rag/answer.ts — l'ancrage se vérifie, il ne se demande pas poliment.

const SYSTEM = `Tu réponds UNIQUEMENT à partir des passages fournis.
Chaque affirmation doit être suivie de sa source au format [S1], [S2].
Si les passages ne contiennent pas la réponse, réponds exactement :
"Je ne trouve pas cette information dans la documentation fournie."
N'utilise jamais tes connaissances générales pour compléter.`;

export async function answer(question: string) {
  const passages = await retrieve(question);

  // Cas explicite : rien de pertinent. On ne laisse pas le modèle improviser.
  if (passages.length === 0) {
    return { text: "Je ne trouve pas cette information dans la documentation fournie.", sources: [] };
  }

  const context = passages
    .map((p, i) => `[S${i + 1}] (${p.sourceUrl})\n${p.text}`)
    .join("\n\n---\n\n");

  const draft = await llm.complete({
    system: SYSTEM,
    user: `Passages :\n${context}\n\nQuestion : ${question}`,
    temperature: 0,          // une réponse factuelle n'a pas à varier
  });

  // Vérification : chaque phrase affirmative porte-t-elle une citation valide ?
  const check = verifyGrounding(draft.text, passages);
  if (!check.ok) {
    logger.warn({ question, unsupported: check.unsupportedClaims }, "réponse non ancrée");
    return { text: "Je ne trouve pas cette information dans la documentation fournie.", sources: [] };
  }

  return { text: draft.text, sources: check.citedSources };
}

