export interface EvalCase {
  id: string;
  input: string;
  category: "nominal" | "edge" | "out_of_scope" | "regression";
  /** Assertions déterministes : rapides, gratuites, non ambiguës. */
  assertions?: Array<(out: string) => boolean>;
  /** Critère pour le juge, uniquement quand le déterministe ne suffit pas. */
  rubric?: string;
  /** Référence issue de l'annotation humaine, pour calibrer le juge. */
  humanScore?: number;
}

export const CASES: EvalCase[] = [
  {
    id: "nominal-refund-policy",
    input: "Quelle est la politique de remboursement au-delà de 30 jours ?",
    category: "nominal",
    assertions: [
      (o) => /\[S\d+\]/.test(o),                  // au moins une citation
      (o) => o.length < 1500,
      (o) => !/je ne trouve pas/i.test(o),
    ],
    rubric: "La réponse mentionne le délai de 30 jours et la procédure d'exception.",
  },
  {
    id: "oos-weather",
    input: "Quel temps fera-t-il demain à Cotonou ?",
    category: "out_of_scope",
    // Le refus est la BONNE réponse. Sans ces cas, on optimise un système bavard.
    assertions: [(o) => /je ne trouve pas/i.test(o)],
  },
  {
    id: "regression-2026-03-11",
    // Incident réel : le modèle inventait un numéro de téléphone d'assistance.
    input: "Quel est le numéro du service client ?",
    category: "regression",
    assertions: [(o) => !/\+?\d[\d\s().-]{7,}/.test(o) || o.includes("[S")],
  },
];

// ---------------------------------------------------------------------------
// eval/run.ts — comparaison à un point de référence, jamais en absolu.

export async function runEval(variant: string) {
  const results = await Promise.all(
    CASES.map(async (c) => {
      const out = await answer(c.input);
      const deterministic = (c.assertions ?? []).every((fn) => fn(out.text));
      // Le juge n'est appelé que si le déterministe passe : inutile de payer sinon.
      const judged = deterministic && c.rubric ? await judge(c, out.text) : null;
      return { id: c.id, category: c.category, deterministic, judgeScore: judged?.score ?? null };
    }),
  );

  const baseline = loadBaseline();
  const regressions = results.filter(
    (r) => baseline[r.id]?.pass && !r.deterministic,
  );

  // Une amélioration moyenne qui casse des cas qui passaient n'est pas acceptable.
  if (regressions.length > 0) {
    console.error(`${regressions.length} régression(s) :`, regressions.map((r) => r.id));
    process.exit(1);
  }
  return summarize(results);
}

// ---------------------------------------------------------------------------
// eval/judge.ts — un juge se CALIBRE, sinon il mesure on ne sait quoi.

export async function calibrateJudge(annotated: EvalCase[]) {
  const scores = await Promise.all(annotated.map((c) => judge(c, c.referenceOutput!)));
  const agreement = cohensKappa(
    scores.map((s) => s.score >= 3),
    annotated.map((c) => c.humanScore! >= 3),
  );
  // En dessous de 0,6, le juge n'est pas exploitable : revoir la grille.
  if (agreement < 0.6) throw new Error(`Accord juge/humain insuffisant : kappa ${agreement.toFixed(2)}`);
  return agreement;
}

