const PII = [
  { name: "email", re: /[\w.+-]+@[\w-]+\.[\w.]+/g },
  { name: "carte", re: /\b(?:\d[ -]?){13,16}\b/g },
];

export function guardOutput(text: string, ctx: { systemPrompt: string }) {
  const violations: string[] = [];

  for (const p of PII) if (p.re.test(text)) violations.push(`pii:${p.name}`);
  if (text.length > 4000) violations.push("length");
  // Fuite du prompt système : comparaison par n-grammes, pas par égalité.
  if (sharedNgrams(text, ctx.systemPrompt, 8) > 0) violations.push("system_prompt_leak");

  // UNE seule reprise avec l'erreur en retour, puis repli déterministe.
  // Boucler indéfiniment sur un modèle qui échoue coûte cher sans converger.
  return violations.length === 0
    ? { ok: true as const, text }
    : { ok: false as const, violations };
}

// src/ai/router.ts — le levier le plus rentable est de ne pas appeler le gros modèle.

const SMALL = "modele-rapide";
const LARGE = "modele-capable";

export async function routeAndAnswer(question: string, ctx: Ctx) {
  // 1. Cache sémantique : les questions équivalentes ne sont pas identiques au caractère près.
  const cached = await semanticCache.get(question, { threshold: 0.95 });
  if (cached) {
    metrics.increment("ai.cache.hit");
    return cached;                       // coût : 0
  }

  // 2. Classification par un PETIT modèle : trancher ne demande pas le gros.
  const kind = await classify(question, { model: SMALL, maxTokens: 5 });

  if (kind === "greeting" || kind === "out_of_scope") {
    return DETERMINISTIC_REPLIES[kind];  // coût : quasi nul, latence : nulle
  }

  const model = kind === "complex_reasoning" ? LARGE : SMALL;
  const result = await callWithResilience({ model, question, ctx });

  await semanticCache.set(question, result, { ttlSeconds: 3600 });
  return result;
}

// ---------------------------------------------------------------------------
// src/ai/resilience.ts — un fournisseur est une dépendance comme une autre.

const breaker = new CircuitBreaker({ failureThreshold: 5, resetTimeoutMs: 30_000 });

export async function callWithResilience(args: CallArgs) {
  if (breaker.isOpen()) return await fallbackAnswer(args);   // on n'insiste pas

  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const res = await llm.complete({
        ...args,
        maxTokens: 800,                                  // sortie BORNÉE : coût prévisible
        signal: AbortSignal.timeout(attempt === 0 ? 8_000 : 15_000),
      });
      breaker.recordSuccess();
      recordCost(args.model, res.usage, args.ctx.conversationId);
      return res;
    } catch (e) {
      breaker.recordFailure();
      // 429 et 5xx se réessaient ; une erreur de requête, jamais.
      if (!isRetryable(e) || attempt === 2) {
        if (args.model === LARGE) return callWithResilience({ ...args, model: SMALL });
        return await fallbackAnswer(args);
      }
      // Recul exponentiel avec bruit : sans le bruit, tous les clients reviennent ensemble.
      await sleep(2 ** attempt * 500 + Math.random() * 300);
    }
  }
}

// ---------------------------------------------------------------------------
// src/ai/cost.ts — le coût se mesure par unité MÉTIER, pas par appel.

export function recordCost(model: string, usage: Usage, conversationId: string) {
  const eur = usage.promptTokens * PRICE[model].in + usage.completionTokens * PRICE[model].out;

  metrics.histogram("ai.cost.per_call_eur", eur, { model });
  // L'agrégat qui décide : combien coûte une conversation du début à la fin.
  metrics.addToConversation(conversationId, eur);

  // Garde-fou dur : une boucle d'agent emballée est détectée en vol, pas sur la facture.
  if (metrics.conversationCost(conversationId) > MAX_EUR_PER_CONVERSATION) {
    throw new BudgetExceededError(conversationId);
  }
}

// ---------------------------------------------------------------------------
// src/ai/stream.ts — la latence perçue compte plus que la latence totale.

export async function streamAnswer(question: string, reply: FastifyReply) {
  const started = performance.now();
  let firstToken = true;

  // Récupération et préparation en parallèle : étapes indépendantes.
  const [passages, profile] = await Promise.all([retrieve(question), loadProfile()]);

  for await (const chunk of llm.stream({ passages, profile, question })) {
    if (firstToken) {
      metrics.histogram("ai.ttft_ms", performance.now() - started);   // l'indicateur clé
      firstToken = false;
    }
    reply.raw.write(`data: ${JSON.stringify({ delta: chunk })}\n\n`);
  }
  reply.raw.end("data: [DONE]\n\n");
}

