// 1 — UNITAIRE : une règle métier pure. Niveau le plus bas qui l'atteste.
// Pas de base, pas de réseau, pas d'horloge réelle.

// src/domain/pricing.ts
export function computeTotal(lines: Line[], discount: Discount | null): number {
  const subtotal = lines.reduce((s, l) => s + l.unitAmount * l.quantity, 0);
  if (!discount) return subtotal;
  return discount.kind === "percentage"
    ? Math.round(subtotal * (1 - discount.value / 100))
    : Math.max(0, subtotal - discount.value);
}

