# .github/workflows/ci.yml
# Un point de contrôle unique agrège tout. Les travaux rapides et discriminants
# s'exécutent en premier : le retour arrive en une minute, pas en dix.

name: CI
on: [pull_request, push]

# Une nouvelle poussée annule l'exécution précédente : inutile de payer pour
# valider un commit déjà remplacé.
concurrency:
  group: ci-${{ github.ref }}
  cancel-in-progress: true

jobs:
  static:
    name: Types, analyse statique et format
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with: { node-version: 22, cache: npm }   # cache des dépendances
      - run: npm ci --legacy-peer-deps
      - run: npx tsc --noEmit
      - run: npm run lint
      - run: npx prettier --check .

  unit:
    runs-on: ubuntu-latest
    strategy:
      # Répartition sur 4 exécutants : ~8 min deviennent ~2 min.
      matrix: { shard: [1, 2, 3, 4] }
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with: { node-version: 22, cache: npm }
      - run: npm ci --legacy-peer-deps
      - run: npx vitest run --shard=${{ matrix.shard }}/4 --reporter=junit --outputFile=r.xml
      - uses: actions/upload-artifact@v4
        if: always()                              # les résultats servent AUSSI en échec
        with: { name: unit-${{ matrix.shard }}, path: r.xml }

  integration:
    runs-on: ubuntu-latest
    services:
      postgres:
        image: postgres:16-alpine
        env: { POSTGRES_PASSWORD: test }
        # Sans contrôle de santé, les tests démarrent avant la base.
        options: >-
          --health-cmd pg_isready --health-interval 5s --health-retries 10
        ports: ["5432:5432"]
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with: { node-version: 22, cache: npm }
      - run: npm ci --legacy-peer-deps
      - run: npx prisma migrate deploy        # les migrations RÉELLES
      - run: npx vitest run --project integration

  # ---------------------------------------------------------------------------
  # Le point de contrôle. C'est LUI qui est déclaré obligatoire dans la
  # protection de branche — un seul nom à maintenir quand les travaux évoluent.
  gate:
    name: Point de contrôle qualité
    runs-on: ubuntu-latest
    needs: [static, unit, integration, e2e]
    # if: always() est indispensable : sans lui, le travail est SAUTÉ quand une
    # dépendance échoue, et un travail sauté est compté comme réussi par
    # la protection de branche. Le contrôle serait alors décoratif.
    if: always()
    steps:
      - name: Vérifier que toutes les dépendances ont réussi
        run: |
          echo '${{ toJSON(needs) }}'             | jq -e 'to_entries | map(select(.value.result != "success")) | length == 0'             || { echo "::error::Un ou plusieurs contrôles ont échoué."; exit 1; }

# Protection de branche : « Point de contrôle qualité » en vérification requise,
# plus l'interdiction de fusionner une branche non à jour.

// ---------------------------------------------------------------------------
// scripts/flake-report.ts — l'instabilité est un défaut, pas une fatalité.

const results = parseJUnitAll("artifacts/**/r.xml");
// Un test qui échoue puis passe à la reprise est instable, même si le travail est vert.
const flaky = results.filter((t) => t.retries > 0 && t.finalStatus === "passed");

for (const t of flaky) {
  const rate = await flakeRateOverWindow(t.name, { days: 30 });
  if (rate > 0.02) {
    // Quarantaine ET ticket. « On relance » est ce qui détruit la crédibilité
    // du point de contrôle : on finit par relancer aussi les vrais échecs.
    await quarantine(t.name);
    await openIssue({ title: `Test instable : ${t.name}`, body: `Taux : ${(rate * 100).toFixed(1)} %` });
  }
}

// ---------------------------------------------------------------------------
// scripts/annotate.ts — un échec doit DIAGNOSTIQUER, pas seulement refuser.

for (const failure of failures) {
  // Annotation directement sur la ligne concernée dans la revue.
  console.log(
    `::error file=${failure.file},line=${failure.line}::` +
      `${failure.metric} = ${failure.actual} (attendu ${failure.expected}). Trace : ${failure.traceUrl}`,
  );
}

