const tracer = trace.getTracer("api");

export async function tracedPayment(req: FastifyRequest, input: PaymentInput) {
  return tracer.startActiveSpan("payment.process", async (span) => {
    // Attributs à faible cardinalité : utilisables en filtre et en agrégat.
    span.setAttributes({
      "payment.currency": input.currency,
      "payment.amount_bucket": bucket(input.amount),   // pas le montant exact
      "user.plan": req.user.plan,
    });
    try {
      // Chaque dépendance a son propre span : on voit laquelle est lente.
      const auth = await tracer.startActiveSpan("payment.authorize", (s) =>
        gateway.authorize(input).finally(() => s.end()),
      );
      const saved = await tracer.startActiveSpan("payment.persist", (s) =>
        db.payment.create({ data: auth }).finally(() => s.end()),
      );
      span.setStatus({ code: SpanStatusCode.OK });
      return saved;
    } catch (e) {
      span.recordException(e as Error);
      span.setStatus({ code: SpanStatusCode.ERROR });
      throw e;
    } finally {
      span.end();
    }
  });
}

