export const sampler = {
  shouldSample(ctx: SampleContext) {
    if (ctx.attributes["http.status_code"] >= 500) return ALWAYS;   // toutes les erreurs
    if (ctx.attributes["duration_ms"] > 1000) return ALWAYS;        // toutes les lenteurs
    return RATIO(0.01);                                             // le reste échantillonné
  },
};

