// src/flags/index.ts
// Une bascule sans date de retrait devient une branche permanente non testée.

export interface Flag {
  key: string;
  owner: string;
  /** Obligatoire : la revue mensuelle liste les bascules périmées. */
  removeBy: string;
  rollout: { percentage: number; allowList?: string[]; denyList?: string[] };
}

export function isEnabled(key: string, ctx: EvalContext): boolean {
  const flag = registry.get(key);
  if (!flag) return false;                         // défaut sûr : désactivé

  if (flag.rollout.denyList?.includes(ctx.accountId)) return false;
  if (flag.rollout.allowList?.includes(ctx.accountId)) return true;

  // Hachage stable : un même compte reçoit TOUJOURS la même décision.
  // Sans cela, un utilisateur voit la fonctionnalité apparaître et disparaître.
  const bucket = murmur3(`${key}:${ctx.accountId}`) % 100;
  return bucket < flag.rollout.percentage;
}

