// ---------------------------------------------------------------------------
// scripts/progressive-rollout.ts — les critères sont évalués, pas interprétés.

const STAGES = [
  { percentage: 1, soakMinutes: 30 },
  { percentage: 10, soakMinutes: 120 },
  { percentage: 50, soakMinutes: 720 },
  { percentage: 100, soakMinutes: 0 },
];

async function promote(flagKey: string) {
  const baseline = await captureBaseline({ minutes: 60 });

  for (const stage of STAGES) {
    await setRollout(flagKey, stage.percentage);
    log.info(`Palier ${stage.percentage} % — observation ${stage.soakMinutes} min`);
    await sleep(stage.soakMinutes * 60_000);

    // Comparaison exposés contre non exposés : isole l'effet de la bascule
    // des variations générales de trafic.
    const m = await compareCohorts(flagKey, { minutes: stage.soakMinutes });

    const failures = [
      m.errorRateDelta > 0.001 && `erreurs +${(m.errorRateDelta * 100).toFixed(2)} pt`,
      m.p95Ratio > 1.1 && `p95 ×${m.p95Ratio.toFixed(2)}`,
      m.budgetBurn > 0.05 && `budget consommé ${(m.budgetBurn * 100).toFixed(1)} %`,
    ].filter(Boolean);

    if (failures.length > 0) {
      // Désactivation immédiate : on n'attend pas de comprendre.
      await setRollout(flagKey, 0);
      await alert("#deploys", `Déploiement annulé à ${stage.percentage} % : ${failures.join(", ")}`);
      process.exit(1);
    }
  }
  await scheduleFlagRemoval(flagKey, { weeks: 2 });
}

