// ---------------------------------------------------------------------------
// scripts/compare-perf.mjs — on compare, on n'évalue pas dans l'absolu.

const base = await loadMetrics(argv.base);
const head = await loadMetrics(argv.head);

const regressions = Object.entries(BUDGETS).flatMap(([metric, budget]) => {
  const delta = head[metric] - base[metric];
  const overBudget = head[metric] > budget;
  // Tolérance de 2 % : sous ce seuil, c'est du bruit de mesure.
  const significant = delta / base[metric] > 0.02;

  return overBudget || significant
    ? [{ metric, base: base[metric], head: head[metric], delta, overBudget }]
    : [];
});

await commentOnPR(formatTable(regressions));   // la cause est évidente le jour même
if (regressions.some((r) => r.overBudget)) process.exit(1);

